#!/usr/bin/env python3
"""
serpl - A simple terminal UI for search and replace, ala VS Code
"""

import curses
import sys
import os
import re
import json
import subprocess
import signal
import time
import threading
from pathlib import Path
from typing import Optional, List, Tuple, Dict, Any
from enum import Enum, auto

VERSION = "0.3.4-"
BUILD_DATE = "2026-04-20"
AUTHOR = "Yassine Bridi <ybridi@gmail.com>"

class SearchMode(Enum):
    SIMPLE = "Simple"
    MATCH_CASE = "Match Case"
    MATCH_WHOLE_WORD = "Match Whole Word"
    MATCH_CASE_WHOLE_WORD = "Match Case Whole Word"
    REGEX = "Regex"

SEARCH_MODES = [
    SearchMode.SIMPLE,
    SearchMode.MATCH_CASE,
    SearchMode.MATCH_WHOLE_WORD,
    SearchMode.MATCH_CASE_WHOLE_WORD,
    SearchMode.REGEX,
]

class ReplaceMode(Enum):
    SIMPLE = "Simple"
    PRESERVE_CASE = "Preserve Case"
    DELETE_LINE = "Delete Line"

REPLACE_MODES = [
    ReplaceMode.SIMPLE,
    ReplaceMode.PRESERVE_CASE,
    ReplaceMode.DELETE_LINE,
]

class ActivePane(Enum):
    SEARCH = auto()
    REPLACE = auto()
    RESULTS = auto()

class ResultItem:
    """A file with its matches"""
    def __init__(self, path: str, matches: List[Dict]):
        self.path = path
        self.matches = matches  # list of {line_number, line_content, submatches: [{start, end}]}
        self.is_excluded = False  # 'd' key on file level removes from replacement

class MatchItem:
    """A single match within a file"""
    def __init__(self, result: 'ResultItem', match_idx: int):
        self.result = result
        self.match_idx = match_idx
        self.is_excluded = False  # 'd' key on match level

def parse_json5(text):
    """Parse JSON5 (JSON with comments and trailing commas)"""
    # Remove single-line comments
    text = re.sub(r'//[^\n]*', '', text)
    # Remove multi-line comments
    text = re.sub(r'/\*.*?\*/', '', text, flags=re.DOTALL)
    # Remove trailing commas before } or ]
    text = re.sub(r',\s*([}\]])', r'\1', text)
    return json.loads(text)

def load_config():
    """Load configuration from config directory"""
    config_dir = Path.home() / '.config' / 'serpl'
    config_file = config_dir / 'config.json5'

    default_config = {
        "keybindings": {
            "<Ctrl-d>": "Quit",
            "<Ctrl-c>": "Quit",
            "<Ctrl-z>": "Suspend",
            "<Ctrl-r>": "Refresh",
            "<Tab>": "LoopOverTabs",
            "<Backtab>": "BackLoopOverTabs",
            "<Ctrl-o>": "ProcessReplace",
            "<Ctrl-b>": "ShowHelp",
        }
    }

    if config_file.exists():
        try:
            with open(config_file) as f:
                content = f.read()
            config = parse_json5(content)
            return config
        except:
            pass

    return default_config

def run_ripgrep(pattern: str, project_root: str, search_mode: SearchMode) -> List[ResultItem]:
    """Run ripgrep and return results"""
    if not pattern:
        return []

    cmd = ['rg', '--json']

    if search_mode == SearchMode.SIMPLE:
        cmd += ['-i', '-F']
    elif search_mode == SearchMode.MATCH_CASE:
        cmd += ['-F']
    elif search_mode == SearchMode.MATCH_WHOLE_WORD:
        cmd += ['-i', '-w', '-F']
    elif search_mode == SearchMode.MATCH_CASE_WHOLE_WORD:
        cmd += ['-w', '-F']
    elif search_mode == SearchMode.REGEX:
        pass  # No extra flags for regex

    cmd += [pattern, project_root]

    try:
        result = subprocess.run(cmd, capture_output=True, text=True, timeout=30)
        output = result.stdout
    except subprocess.TimeoutExpired:
        return []
    except Exception:
        return []

    # Parse JSON output
    files: Dict[str, ResultItem] = {}
    current_file = None

    for line in output.splitlines():
        if not line.strip():
            continue
        try:
            data = json.loads(line)
        except json.JSONDecodeError:
            continue

        msg_type = data.get('type')

        if msg_type == 'begin':
            path = data['data']['path']['text']
            current_file = path
            if path not in files:
                files[path] = ResultItem(path, [])

        elif msg_type == 'match' and current_file:
            match_data = data['data']
            line_number = match_data['line_number']
            line_content = match_data['lines']['text'].rstrip('\n')
            submatches = [
                {'start': sm['start'], 'end': sm['end']}
                for sm in match_data['submatches']
            ]
            files[current_file].matches.append({
                'line_number': line_number,
                'line_content': line_content,
                'submatches': submatches,
            })

    return list(files.values())

def preserve_case_replace(original: str, replacement: str) -> str:
    """Apply case preservation to replacement string based on original's case"""
    if original.isupper():
        return replacement.upper()
    elif original.islower():
        return replacement.lower()
    elif original[0].isupper() if original else False:
        # Title case - capitalize first letter
        if replacement:
            return replacement[0].upper() + replacement[1:].lower()
        return replacement
    return replacement

def apply_replacement_to_line(line: str, submatches: List[Dict], 
                               replacement: str, replace_mode: ReplaceMode) -> Optional[str]:
    """Apply replacement to a line based on mode. Returns None for delete_line."""
    if replace_mode == ReplaceMode.DELETE_LINE:
        return None

    if not replacement and replace_mode == ReplaceMode.SIMPLE:
        # Empty replacement means delete the matched text
        pass

    # Apply replacements from right to left to preserve positions
    result = line
    for sm in reversed(submatches):
        start, end = sm['start'], sm['end']
        original_match = line[start:end]

        if replace_mode == ReplaceMode.PRESERVE_CASE:
            actual_replacement = preserve_case_replace(original_match, replacement)
        else:
            actual_replacement = replacement

        result = result[:start] + actual_replacement + result[end:]

    return result

def apply_replacement_to_file(result_item: ResultItem, search_pattern: str,
                               replacement: str, replace_mode: ReplaceMode,
                               search_mode: SearchMode,
                               excluded_matches: Optional[set] = None) -> bool:
    """Apply replacement to entire file. Returns True on success."""
    path = result_item.path

    try:
        with open(path, 'r', encoding='utf-8', errors='replace') as f:
            lines = f.readlines()
    except Exception:
        return False

    # Build a set of (line_number, match_idx) to process
    lines_to_modify = {}

    for match_idx, match in enumerate(result_item.matches):
        if match_idx in (excluded_matches or set()):
            continue
        line_no = match['line_number']  # 1-indexed
        if line_no not in lines_to_modify:
            lines_to_modify[line_no] = {'submatches': [], 'line_content': match['line_content']}
        lines_to_modify[line_no]['submatches'].extend(match['submatches'])

    if not lines_to_modify:
        return True

    new_lines = []
    for i, line in enumerate(lines):
        line_no = i + 1  # 1-indexed
        if line_no in lines_to_modify:
            # Preserve trailing newline
            has_newline = line.endswith('\n')
            line_stripped = line.rstrip('\n')

            submatches = lines_to_modify[line_no]['submatches']
            # Sort submatches by position, deduplicate
            seen = set()
            unique_submatches = []
            for sm in sorted(submatches, key=lambda x: x['start']):
                key = (sm['start'], sm['end'])
                if key not in seen:
                    seen.add(key)
                    unique_submatches.append(sm)

            result = apply_replacement_to_line(line_stripped, unique_submatches, 
                                                replacement, replace_mode)
            if result is None:
                # Delete line
                pass
            else:
                new_lines.append(result + ('\n' if has_newline else ''))
        else:
            new_lines.append(line)

    try:
        with open(path, 'w', encoding='utf-8') as f:
            f.writelines(new_lines)
        return True
    except Exception:
        return False

CONTEXT_LINES = 3

def get_file_context_groups(result_item: ResultItem, project_root: str) -> List[Dict]:
    """Get context groups for a file's matches for preview display."""
    path = result_item.path
    try:
        with open(path, 'r', encoding='utf-8', errors='replace') as f:
            all_lines = f.readlines()
    except:
        all_lines = []

    total_lines = len(all_lines)
    matches = result_item.matches

    if not matches:
        return []

    groups = []

    for i, match in enumerate(matches):
        match_line = match['line_number']  # 1-indexed

        prev_match = matches[i-1]['line_number'] if i > 0 else 0
        next_match = matches[i+1]['line_number'] if i < len(matches) - 1 else total_lines + 1

        start = max(prev_match, match_line - CONTEXT_LINES)
        end = min(next_match - 1, match_line + CONTEXT_LINES)

        # Clamp to file bounds
        start = max(1, start)
        end = min(total_lines, end)

        group_lines = []
        for line_no in range(start, end + 1):
            if line_no <= len(all_lines):
                content = all_lines[line_no - 1].rstrip('\n')
            else:
                content = ''
            is_match = (line_no == match_line)
            group_lines.append({
                'line_number': line_no,
                'content': content,
                'is_match': is_match,
                'submatches': match['submatches'] if is_match else [],
            })

        groups.append({
            'match_idx': i,
            'match_line': match_line,
            'lines': group_lines,
        })

    return groups


class SerplApp:
    """Main application class"""

    def __init__(self, stdscr, project_root: str, config: dict):
        self.stdscr = stdscr
        self.project_root = project_root
        self.config = config

        # State
        self.search_text = ""
        self.replace_text = ""
        self.search_mode = SearchMode.SIMPLE
        self.replace_mode = ReplaceMode.SIMPLE
        self.active_pane = ActivePane.SEARCH

        self.results: List[ResultItem] = []
        self.result_selected_idx: Optional[int] = None  # Index in flat result list

        # Navigation state
        self.in_file_expanded = False  # True when navigating matches within a file
        self.match_selected_idx: Optional[int] = None  # Index within current file's matches

        # UI state
        self.show_help = False
        self.help_tab = 0  # 0 = Global, 1 = Navigation
        self.show_confirm = False
        self.confirm_selected = 0  # 0 = Continue, 1 = Cancel
        self.notification: Optional[str] = None
        self.notification_time: float = 0
        self.NOTIFICATION_DURATION = 3.0

        # Preview scroll
        self.preview_scroll = 0

        # Setup colors
        curses.start_color()
        curses.use_default_colors()
        curses.init_pair(1, curses.COLOR_YELLOW, -1)   # Search match highlight
        curses.init_pair(2, curses.COLOR_GREEN, -1)    # Replace highlight  
        curses.init_pair(3, curses.COLOR_RED, -1)      # Error
        curses.init_pair(4, curses.COLOR_CYAN, -1)     # Selected
        curses.init_pair(5, curses.COLOR_WHITE, curses.COLOR_BLUE)  # Active pane title
        curses.init_pair(6, curses.COLOR_BLACK, curses.COLOR_WHITE)  # Confirm selection
        curses.init_pair(7, curses.COLOR_MAGENTA, -1)  # Selected in list
        curses.init_pair(8, curses.COLOR_WHITE, -1)    # Normal text

        # Setup terminal
        curses.noecho()
        curses.cbreak()
        stdscr.keypad(True)
        curses.curs_set(1)  # Show cursor

    def run(self):
        """Main loop"""
        while True:
            self.draw()
            if not self.handle_input():
                break

    def handle_input(self) -> bool:
        """Handle keyboard input. Returns False to quit."""
        try:
            key = self.stdscr.get_wch()
        except curses.error:
            return True

        # Handle notifications
        if self.notification and time.time() - self.notification_time > self.NOTIFICATION_DURATION:
            self.notification = None

        # Help dialog handling
        if self.show_help:
            return self.handle_help_input(key)

        # Confirm dialog handling
        if self.show_confirm:
            return self.handle_confirm_input(key)

        # Global keys
        if key == '\x04' or key == '\x03':  # Ctrl-d, Ctrl-c
            return False

        if key == '\x1a':  # Ctrl-z
            curses.def_prog_mode()
            curses.endwin()
            os.kill(os.getpid(), signal.SIGTSTP)
            curses.reset_prog_mode()
            self.stdscr.refresh()
            return True

        if key == '\x12':  # Ctrl-r (Refresh)
            if self.search_text:
                self.do_search()
            return True

        if key == '\x02':  # Ctrl-b (Help)
            self.show_help = True
            self.help_tab = 0
            return True

        if key == '\x0f':  # Ctrl-o (Process Replace)
            if self.results:
                self.show_confirm = True
                self.confirm_selected = 0
            return True

        # Tab cycling
        if key == '\t':  # Tab
            self.cycle_pane(forward=True)
            return True

        if isinstance(key, str) and key == '\x1b[Z':  # Shift-Tab
            self.cycle_pane(forward=False)
            return True

        if isinstance(key, int) and key == curses.KEY_BTAB:
            self.cycle_pane(forward=False)
            return True

        # Handle by active pane
        if self.active_pane == ActivePane.SEARCH:
            return self.handle_search_input(key)
        elif self.active_pane == ActivePane.REPLACE:
            return self.handle_replace_input(key)
        elif self.active_pane == ActivePane.RESULTS:
            return self.handle_results_input(key)

        return True

    def handle_help_input(self, key) -> bool:
        if key == '\x1b' or key == 'q':  # Escape or q
            self.show_help = False
        elif key == curses.KEY_RIGHT or key == 'l':
            self.help_tab = min(1, self.help_tab + 1)
        elif key == curses.KEY_LEFT or key == 'h':
            self.help_tab = max(0, self.help_tab - 1)
        return True

    def handle_confirm_input(self, key) -> bool:
        if key == '\x1b' or (isinstance(key, int) and key == curses.KEY_LEFT):
            self.show_confirm = False
        elif key == '\n' or key == '\r':
            self.show_confirm = False
            self.do_replace_all()
        return True

    def handle_search_input(self, key) -> bool:
        if key == '\n' or key == '\r':  # Enter = search
            if self.search_text:
                self.do_search()
        elif key == '\x0e':  # Ctrl-n = toggle mode
            idx = SEARCH_MODES.index(self.search_mode)
            self.search_mode = SEARCH_MODES[(idx + 1) % len(SEARCH_MODES)]
            if self.search_text:
                self.do_search()
        elif isinstance(key, int) and key == curses.KEY_BACKSPACE:
            self.search_text = self.search_text[:-1]
        elif key == '\x7f' or key == '\b':
            self.search_text = self.search_text[:-1]
        elif isinstance(key, str) and key.isprintable():
            self.search_text += key
        elif isinstance(key, int) and key >= 32:
            self.search_text += chr(key)
        return True

    def handle_replace_input(self, key) -> bool:
        if key == '\x0e':  # Ctrl-n = toggle replace mode
            idx = REPLACE_MODES.index(self.replace_mode)
            self.replace_mode = REPLACE_MODES[(idx + 1) % len(REPLACE_MODES)]
        elif isinstance(key, int) and key == curses.KEY_BACKSPACE:
            self.replace_text = self.replace_text[:-1]
        elif key == '\x7f' or key == '\b':
            self.replace_text = self.replace_text[:-1]
        elif isinstance(key, str) and key.isprintable():
            self.replace_text += key
        elif isinstance(key, int) and key >= 32:
            self.replace_text += chr(key)
        return True

    def handle_results_input(self, key) -> bool:
        if not self.results:
            return True

        if key == '\x0e':  # Ctrl-n - no mode toggle in results
            pass

        if not self.in_file_expanded:
            # File-level navigation
            return self.handle_file_nav(key)
        else:
            # Match-level navigation
            return self.handle_match_nav(key)

    def handle_file_nav(self, key) -> bool:
        """Handle navigation at file level in results list"""
        num_files = len(self.results)

        if key in (curses.KEY_DOWN, 'k') or (isinstance(key, int) and key == curses.KEY_DOWN):
            if self.result_selected_idx is None:
                self.result_selected_idx = 0
            else:
                self.result_selected_idx = (self.result_selected_idx + 1) % num_files
            self.preview_scroll = 0
        elif key in (curses.KEY_UP, 'j') or (isinstance(key, int) and key == curses.KEY_UP):
            if self.result_selected_idx is None:
                self.result_selected_idx = num_files - 1
            else:
                self.result_selected_idx = (self.result_selected_idx - 1) % num_files
            self.preview_scroll = 0
        elif key in ('j',):
            if self.result_selected_idx is None:
                self.result_selected_idx = 0
            else:
                self.result_selected_idx = (self.result_selected_idx + 1) % num_files
            self.preview_scroll = 0
        elif key in ('k',):
            if self.result_selected_idx is None:
                self.result_selected_idx = num_files - 1
            else:
                self.result_selected_idx = (self.result_selected_idx - 1) % num_files
            self.preview_scroll = 0
        elif key in ('g', 'h') or (isinstance(key, int) and key == curses.KEY_LEFT):
            self.result_selected_idx = 0
            self.preview_scroll = 0
        elif key in ('G', 'l') or (isinstance(key, int) and key == curses.KEY_RIGHT):
            self.result_selected_idx = num_files - 1
            self.preview_scroll = 0
        elif key == '\n' or key == '\r':  # Enter = expand file
            if self.result_selected_idx is not None:
                self.in_file_expanded = True
                self.match_selected_idx = None
                self.preview_scroll = 0
        elif key == 'd':  # Delete file from results
            if self.result_selected_idx is not None:
                del self.results[self.result_selected_idx]
                if not self.results:
                    self.result_selected_idx = None
                elif self.result_selected_idx >= len(self.results):
                    self.result_selected_idx = len(self.results) - 1
                self.preview_scroll = 0
        elif key == 'r':  # Replace selected file
            if self.result_selected_idx is not None:
                self.do_replace_file(self.result_selected_idx)

        return True

    def handle_match_nav(self, key) -> bool:
        """Handle navigation at match level (within expanded file)"""
        if self.result_selected_idx is None:
            return True

        result = self.results[self.result_selected_idx]
        # Count non-excluded matches for navigation
        matches = result.matches
        num_matches = len(matches)

        if key == '\n' or key == '\r':  # Enter = back to file list
            self.in_file_expanded = False
            self.match_selected_idx = None
            self.preview_scroll = 0
        elif key in (curses.KEY_DOWN, 'k') or (isinstance(key, int) and key == curses.KEY_DOWN):
            if self.match_selected_idx is None:
                self.match_selected_idx = 0
            else:
                self.match_selected_idx = (self.match_selected_idx + 1) % num_matches
            self.preview_scroll = 0
        elif key in (curses.KEY_UP, 'j') or (isinstance(key, int) and key == curses.KEY_UP):
            if self.match_selected_idx is None:
                self.match_selected_idx = num_matches - 1
            else:
                self.match_selected_idx = (self.match_selected_idx - 1) % num_matches
            self.preview_scroll = 0
        elif key in ('j',):
            if self.match_selected_idx is None:
                self.match_selected_idx = 0
            else:
                self.match_selected_idx = (self.match_selected_idx + 1) % num_matches
            self.preview_scroll = 0
        elif key in ('k',):
            if self.match_selected_idx is None:
                self.match_selected_idx = num_matches - 1
            else:
                self.match_selected_idx = (self.match_selected_idx - 1) % num_matches
            self.preview_scroll = 0
        elif key in ('g', 'h') or (isinstance(key, int) and key == curses.KEY_LEFT):
            self.match_selected_idx = 0
            self.preview_scroll = 0
        elif key in ('G', 'l') or (isinstance(key, int) and key == curses.KEY_RIGHT):
            self.match_selected_idx = num_matches - 1
            self.preview_scroll = 0
        elif key == 'd':  # Delete match
            if self.match_selected_idx is not None:
                del result.matches[self.match_selected_idx]
                if not result.matches:
                    # File has no more matches, remove it
                    del self.results[self.result_selected_idx]
                    self.in_file_expanded = False
                    self.match_selected_idx = None
                    if self.result_selected_idx >= len(self.results):
                        self.result_selected_idx = len(self.results) - 1 if self.results else None
                else:
                    if self.match_selected_idx >= len(result.matches):
                        self.match_selected_idx = len(result.matches) - 1
                self.preview_scroll = 0
        elif key == 'r':  # Replace selected match
            if self.match_selected_idx is not None:
                self.do_replace_match(self.result_selected_idx, self.match_selected_idx)

        return True

    def cycle_pane(self, forward: bool = True):
        """Cycle through panes"""
        panes = [ActivePane.SEARCH, ActivePane.REPLACE, ActivePane.RESULTS]
        idx = panes.index(self.active_pane)
        if forward:
            idx = (idx + 1) % len(panes)
        else:
            idx = (idx - 1) % len(panes)
        self.active_pane = panes[idx]

        # If we moved to results and have results, pre-select first
        if self.active_pane == ActivePane.RESULTS and self.results:
            if self.result_selected_idx is None:
                pass  # Don't auto-select, wait for Down key

    def do_search(self):
        """Execute the search"""
        self.results = run_ripgrep(self.search_text, self.project_root, self.search_mode)
        self.result_selected_idx = None
        self.in_file_expanded = False
        self.match_selected_idx = None
        self.preview_scroll = 0

    def do_replace_all(self):
        """Replace in all files"""
        for result in self.results:
            apply_replacement_to_file(
                result, self.search_text, self.replace_text,
                self.replace_mode, self.search_mode
            )
        if self.search_text:
            self.do_search()

    def do_replace_file(self, file_idx: int):
        """Replace in specific file"""
        if file_idx >= len(self.results):
            return
        result = self.results[file_idx]
        success = apply_replacement_to_file(
            result, self.search_text, self.replace_text,
            self.replace_mode, self.search_mode
        )
        if success:
            self.notification = "File replacement completed successfully"
            self.notification_time = time.time()
            # Remove this file from results
            del self.results[file_idx]
            if self.result_selected_idx is not None:
                if self.result_selected_idx >= len(self.results):
                    self.result_selected_idx = len(self.results) - 1 if self.results else None

    def do_replace_match(self, file_idx: int, match_idx: int):
        """Replace a single match"""
        if file_idx >= len(self.results):
            return
        result = self.results[file_idx]
        if match_idx >= len(result.matches):
            return

        match = result.matches[match_idx]
        path = result.path

        try:
            with open(path, 'r', encoding='utf-8', errors='replace') as f:
                all_lines = f.readlines()
        except Exception:
            return

        line_no = match['line_number']  # 1-indexed
        if line_no <= len(all_lines):
            line = all_lines[line_no - 1]
            has_newline = line.endswith('\n')
            line_stripped = line.rstrip('\n')

            new_line = apply_replacement_to_line(
                line_stripped, match['submatches'],
                self.replace_text, self.replace_mode
            )

            if new_line is None:
                # Delete line
                all_lines.pop(line_no - 1)
            else:
                all_lines[line_no - 1] = new_line + ('\n' if has_newline else '')

            try:
                with open(path, 'w', encoding='utf-8') as f:
                    f.writelines(all_lines)
            except Exception:
                return

        # Remove this match from results
        del result.matches[match_idx]
        if not result.matches:
            del self.results[file_idx]
            self.in_file_expanded = False
            self.match_selected_idx = None
            if self.result_selected_idx is not None and self.result_selected_idx >= len(self.results):
                self.result_selected_idx = len(self.results) - 1 if self.results else None
        else:
            if self.match_selected_idx is not None and self.match_selected_idx >= len(result.matches):
                self.match_selected_idx = len(result.matches) - 1

    def get_dimensions(self):
        """Get screen dimensions and panel sizes"""
        height, width = self.stdscr.getmaxyx()

        # Left panel is 30% of width
        left_width = int(width * 0.30)
        # Minimum width
        left_width = max(left_width, 20)

        # Panel heights
        search_height = 3  # title + content + border
        replace_height = 3
        results_height = height - search_height - replace_height - 1  # -1 for status bar

        right_width = width - left_width
        preview_height = height - 1  # -1 for status bar

        return {
            'height': height,
            'width': width,
            'left_width': left_width,
            'right_width': right_width,
            'search_height': search_height,
            'replace_height': replace_height,
            'results_height': results_height,
            'preview_height': preview_height,
        }

    def draw(self):
        """Draw the entire TUI"""
        dims = self.get_dimensions()
        self.stdscr.erase()

        # Draw main panels
        self.draw_search_panel(dims)
        self.draw_replace_panel(dims)
        self.draw_results_panel(dims)
        self.draw_preview_panel(dims)
        self.draw_status_bar(dims)

        # Draw overlays
        if self.show_help:
            self.draw_help_dialog(dims)
        elif self.show_confirm:
            self.draw_confirm_dialog(dims)

        # Draw notification
        if self.notification and time.time() - self.notification_time < self.NOTIFICATION_DURATION:
            self.draw_notification(dims)

        # Position cursor
        self.position_cursor(dims)

        self.stdscr.refresh()

    def draw_box(self, y, x, height, width, title="", active=False):
        """Draw a rounded box"""
        if height < 2 or width < 2:
            return

        attr = curses.A_BOLD if active else curses.A_NORMAL

        # Top border
        top = '╭' + '─' * (width - 2) + '╮'
        if title:
            # Truncate title to fit
            max_title_len = width - 4
            if len(title) > max_title_len:
                title = title[:max_title_len]
            # Fill dashes on both sides
            available = width - 2 - len(title)
            left_dashes = 1  # at least one dash after ╭
            right_dashes = available - left_dashes
            top = '╭' + '─' * left_dashes + title + '─' * right_dashes + '╮'

        try:
            self.stdscr.addstr(y, x, top[:width], attr)
        except curses.error:
            pass

        # Side borders
        for i in range(1, height - 1):
            try:
                self.stdscr.addstr(y + i, x, '│', attr)
                self.stdscr.addstr(y + i, x + width - 1, '│', attr)
            except curses.error:
                pass

        # Bottom border
        bottom = '╰' + '─' * (width - 2) + '╯'
        try:
            self.stdscr.addstr(y + height - 1, x, bottom[:width], attr)
        except curses.error:
            pass

    def draw_search_panel(self, dims):
        """Draw the search input panel"""
        active = self.active_pane == ActivePane.SEARCH
        left_w = dims['left_width']

        mode_label = f"[{self.search_mode.value}]"
        # Title: "Search────[Mode]"
        inner_width = left_w - 2
        title_text = "Search"
        dashes_total = inner_width - len(title_text) - len(mode_label)
        title = title_text + '─' * max(0, dashes_total) + mode_label
        # Final title for the box: pad or truncate
        if len(title) > inner_width:
            title = title[:inner_width]

        self.draw_box(0, 0, 3, left_w, title=title, active=active)

        # Input text
        text = self.search_text
        max_len = left_w - 2
        if len(text) > max_len:
            text = text[-(max_len):]
        try:
            self.stdscr.addstr(1, 1, text[:max_len].ljust(max_len))
        except curses.error:
            pass

    def draw_replace_panel(self, dims):
        """Draw the replace input panel"""
        active = self.active_pane == ActivePane.REPLACE
        left_w = dims['left_width']

        mode_label = f"[{self.replace_mode.value}]"
        inner_width = left_w - 2
        title_text = "Replace"
        dashes_total = inner_width - len(title_text) - len(mode_label)
        title = title_text + '─' * max(0, dashes_total) + mode_label
        if len(title) > inner_width:
            title = title[:inner_width]

        y = dims['search_height']
        self.draw_box(y, 0, 3, left_w, title=title, active=active)

        # Input text
        text = self.replace_text
        if self.replace_mode == ReplaceMode.DELETE_LINE:
            text = "[Entire line will be deleted]"
        max_len = left_w - 2
        if len(text) > max_len:
            text = text[:max_len]
        try:
            self.stdscr.addstr(y + 1, 1, text[:max_len].ljust(max_len))
        except curses.error:
            pass

    def draw_results_panel(self, dims):
        """Draw the results list panel"""
        active = self.active_pane == ActivePane.RESULTS
        left_w = dims['left_width']
        y_start = dims['search_height'] + dims['replace_height']
        panel_height = dims['results_height']

        self.draw_box(y_start, 0, panel_height, left_w, title="Result List", active=active)

        if not self.results:
            return

        inner_h = panel_height - 2
        inner_w = left_w - 2

        # Calculate visible range
        # Each file takes 1 row
        for i, result in enumerate(self.results):
            if i >= inner_h:
                break

            # Display relative path
            rel_path = os.path.relpath(result.path, self.project_root)
            match_count = len(result.matches)

            text = f"{rel_path} ({match_count})"
            if len(text) > inner_w:
                text = text[:inner_w]

            row = y_start + 1 + i

            is_selected = (i == self.result_selected_idx)

            if is_selected:
                attr = curses.A_REVERSE
            else:
                attr = curses.A_NORMAL

            try:
                self.stdscr.addstr(row, 1, text.ljust(inner_w), attr)
            except curses.error:
                pass

    def get_preview_content(self) -> List[Dict]:
        """Get the content to display in the preview panel"""
        if self.result_selected_idx is None:
            return []

        if self.result_selected_idx >= len(self.results):
            return []

        result = self.results[self.result_selected_idx]
        groups = get_file_context_groups(result, self.project_root)

        if not groups:
            return []

        # Build display lines
        display_lines = []

        for group_idx, group in enumerate(groups):
            for line_info in group['lines']:
                is_selected_match = (
                    self.in_file_expanded and 
                    self.match_selected_idx is not None and
                    group['match_idx'] == self.match_selected_idx and
                    line_info['is_match']
                )

                display_lines.append({
                    'line_number': line_info['line_number'],
                    'content': line_info['content'],
                    'is_match': line_info['is_match'],
                    'submatches': line_info['submatches'],
                    'is_selected': is_selected_match,
                    'group_idx': group_idx,
                    'match_idx': group['match_idx'],
                })

            # Add separator after each group
            display_lines.append({'separator': True, 'group_idx': group_idx})

        return display_lines

    def draw_preview_panel(self, dims):
        """Draw the preview panel"""
        left_w = dims['left_width']
        right_w = dims['right_width']
        height = dims['preview_height']
        x = left_w

        # Draw top border (connected to left panel)
        top = '╭' + 'Preview' + '─' * (right_w - 2 - len('Preview')) + '╮'
        try:
            self.stdscr.addstr(0, x, top[:right_w])
        except curses.error:
            pass

        # Draw side borders and content
        inner_w = right_w - 2
        inner_h = height - 2

        preview_lines = self.get_preview_content()

        # Determine line number field width based on current file
        ln_field_width = 4  # default
        if self.result_selected_idx is not None and self.result_selected_idx < len(self.results):
            result = self.results[self.result_selected_idx]
            if result.matches:
                max_line = max(m['line_number'] for m in result.matches)
                # Get total file lines for context
                try:
                    with open(result.path, 'r') as f:
                        total = sum(1 for _ in f)
                    max_line = max(max_line + CONTEXT_LINES, total)
                except:
                    pass
                ln_field_width = len(str(max_line))
                if ln_field_width < 4:
                    ln_field_width = 4

        # Draw content
        for row_idx in range(inner_h):
            display_row = row_idx + self.preview_scroll
            row_y = 1 + row_idx

            try:
                self.stdscr.addstr(row_y, x, '│')
                self.stdscr.addstr(row_y, x + right_w - 1, '│')
            except curses.error:
                pass

            if display_row < len(preview_lines):
                line = preview_lines[display_row]

                if line.get('separator'):
                    # Draw separator
                    if self.in_file_expanded:
                        sep_content = '  ' + '-' * (inner_w - 2)
                    else:
                        sep_content = '-' * inner_w
                    try:
                        self.stdscr.addstr(row_y, x + 1, sep_content[:inner_w])
                    except curses.error:
                        pass
                else:
                    # Draw line content
                    line_no = line['line_number']
                    content = line['content']
                    is_match = line['is_match']
                    is_selected = line['is_selected']
                    submatches = line['submatches']

                    if self.in_file_expanded:
                        # Match-level format: indicator + 5-char-number + space
                        indicator = '>' if is_selected else ' '
                        line_no_str = f"{line_no:5d}"
                        prefix = indicator + line_no_str + ' '
                    else:
                        # File-level format: 4-char-number + space
                        line_no_str = f"{line_no:4d}"
                        prefix = line_no_str + ' '

                    prefix_len = len(prefix)
                    max_content = inner_w - prefix_len

                    # Build line with replacement preview
                    if is_match and self.replace_text:
                        # Show match + replacement inline
                        display_content = self.build_match_display(content, submatches, max_content)
                    else:
                        display_content = content

                    if len(display_content) > max_content:
                        display_content = display_content[:max_content]

                    full_line = prefix + display_content.ljust(max_content)

                    try:
                        if is_selected:
                            self.stdscr.addstr(row_y, x + 1, prefix, curses.A_BOLD)
                            pos = x + 1 + prefix_len
                            # Draw content with highlighting
                            self.draw_match_content(row_y, pos, display_content, 
                                                     submatches, max_content, is_match)
                        elif is_match:
                            self.stdscr.addstr(row_y, x + 1, prefix)
                            pos = x + 1 + prefix_len
                            self.draw_match_content(row_y, pos, display_content,
                                                     submatches, max_content, is_match)
                        else:
                            self.stdscr.addstr(row_y, x + 1, full_line[:inner_w])
                    except curses.error:
                        pass

        # Bottom border
        try:
            bottom = '╰' + '─' * (right_w - 2) + '╯'
            self.stdscr.addstr(height - 1, x, bottom[:right_w])
        except curses.error:
            pass

    def build_match_display(self, content: str, submatches: List[Dict], max_len: int) -> str:
        """Build display string showing match + replacement inline"""
        if not submatches:
            return content[:max_len]

        result = ''
        prev_end = 0

        for sm in sorted(submatches, key=lambda x: x['start']):
            start, end = sm['start'], sm['end']
            result += content[prev_end:start]
            result += content[start:end]  # Original match
            result += self.replace_text  # Replacement text
            prev_end = end

        result += content[prev_end:]
        return result[:max_len]

    def draw_match_content(self, y, x, content, submatches, max_len, is_match):
        """Draw content with match/replace highlighting"""
        if not is_match or not submatches:
            try:
                self.stdscr.addstr(y, x, content[:max_len].ljust(max_len))
            except curses.error:
                pass
            return

        # Draw with color highlights
        pos = 0
        screen_x = x

        for sm in sorted(submatches, key=lambda s: s['start']):
            start, end = sm['start'], sm['end']

            # Text before match
            before = content[pos:start]
            if before and screen_x < x + max_len:
                remaining = x + max_len - screen_x
                try:
                    self.stdscr.addstr(y, screen_x, before[:remaining])
                except curses.error:
                    pass
                screen_x += len(before[:remaining])

            # Match text
            match_text = content[start:end]
            if match_text and screen_x < x + max_len:
                remaining = x + max_len - screen_x
                try:
                    self.stdscr.addstr(y, screen_x, match_text[:remaining], 
                                       curses.color_pair(1) | curses.A_BOLD)
                except curses.error:
                    pass
                screen_x += len(match_text[:remaining])

            # Replacement text
            if self.replace_text and screen_x < x + max_len:
                remaining = x + max_len - screen_x
                try:
                    self.stdscr.addstr(y, screen_x, self.replace_text[:remaining],
                                       curses.color_pair(2) | curses.A_BOLD)
                except curses.error:
                    pass
                screen_x += len(self.replace_text[:remaining])

            pos = end

        # Remaining content
        after = content[pos:]
        if after and screen_x < x + max_len:
            remaining = x + max_len - screen_x
            try:
                self.stdscr.addstr(y, screen_x, after[:remaining])
            except curses.error:
                pass
            screen_x += len(after[:remaining])

        # Pad to max_len
        if screen_x < x + max_len:
            try:
                self.stdscr.addstr(y, screen_x, ' ' * (x + max_len - screen_x))
            except curses.error:
                pass

    def draw_status_bar(self, dims):
        """Draw the status bar at the bottom"""
        height = dims['height']
        width = dims['width']
        y = height - 1

        status = self.get_status_text(dims)

        try:
            self.stdscr.addstr(y, 0, status[:width])
        except curses.error:
            pass

    def get_status_text(self, dims) -> str:
        """Get the status bar text based on current state"""
        width = dims['width']

        if self.show_help:
            base = "Close Help: <Esc> | Next Tab: <Right> | Previous Tab:"
            if width >= 80:
                base += " <Left>"
            return base

        if self.show_confirm:
            return "Confirm Replace: <Enter> | Cancel Replace: <Esc>, Left:"

        if self.active_pane == ActivePane.SEARCH:
            base = "Help: <Ctrl-b> | Search: <Enter> | Toggle search mode:"
            if width >= 100:
                base += " <Ctrl-n>"
            return base

        if self.active_pane == ActivePane.REPLACE:
            base = "Help: <Ctrl-b> | Replace: <C-o> | Toggle replace mode:"
            if width >= 100:
                base += " <Ctrl-n>"
            return base

        if self.active_pane == ActivePane.RESULTS:
            if self.in_file_expanded:
                base = "Help: <Ctrl-b> | Back to list: <Enter> | Replace Line:"
                if width >= 100:
                    base += " <r>"
                return base
            else:
                base = "Help: <Ctrl-b> | Open File: <Enter> | Replace File: <r>"
                return base

        return ""

    def draw_help_dialog(self, dims):
        """Draw the help dialog overlay"""
        height = dims['height']
        width = dims['width']

        # Dialog size
        dialog_w = min(width - 4, 80)
        dialog_h = min(height - 4, 18)

        # Center dialog (roughly)
        dialog_y = 4  # Position it to overlay the replace area
        dialog_x = 0

        # Clear the dialog area
        for i in range(dialog_h):
            try:
                self.stdscr.addstr(dialog_y + i, dialog_x, ' ' * dialog_w)
            except curses.error:
                pass

        # Draw dialog box with tab titles
        tabs = "[1] Global ─ [2] Navigation"
        close_hint = "Press 'q' to close"
        inner_w = dialog_w - 2
        title_content = " " + tabs + " " + '─' * max(0, inner_w - len(tabs) - 2 - len(close_hint)) + close_hint

        # Top border
        top = '╭' + title_content[:inner_w] + '╮'
        try:
            self.stdscr.addstr(dialog_y, dialog_x, top[:dialog_w])
        except curses.error:
            pass

        # Side borders
        for i in range(1, dialog_h - 1):
            try:
                self.stdscr.addstr(dialog_y + i, dialog_x, '│')
                self.stdscr.addstr(dialog_y + i, dialog_x + dialog_w - 1, '│')
            except curses.error:
                pass

        # Bottom border
        try:
            self.stdscr.addstr(dialog_y + dialog_h - 1, dialog_x, '╰' + '─' * inner_w + '╯')
        except curses.error:
            pass

        # Content
        if self.help_tab == 0:
            content_lines = [
                "",
                "- Ctrl-c: Quit",
                "- Ctrl-d: Quit",
                "- Ctrl-b: Help dialog",
                "- Ctrl-o: Process Replace For All Files",
                "- Ctrl-n: Loop through search and replace modes",
                "- Enter: Select/Deselect file",
                "- d: delete file/delete line from the replace process",
                "- r: Replace Selected File Or Line",
                "",
            ]
        else:
            content_lines = [
                "",
                "- Tab: Loop through panes",
                "- j/UpArrow: Move up",
                "- k/DownArrow: Move down",
                "- h/g/LeftArrow: Move to Top",
                "- l/G/RightArrow: Move to Bottom",
                "",
            ]

        for i, line in enumerate(content_lines):
            if i + 1 >= dialog_h - 1:
                break
            try:
                self.stdscr.addstr(dialog_y + 1 + i, dialog_x + 1, 
                                   line[:inner_w].ljust(inner_w))
            except curses.error:
                pass

    def draw_confirm_dialog(self, dims):
        """Draw the confirm replace dialog"""
        height = dims['height']
        width = dims['width']

        dialog_w = min(width - 4, 56)
        dialog_h = 8

        # Center horizontally, position vertically
        dialog_x = max(0, (width - dialog_w) // 2 - 5)
        dialog_y = max(0, (height - dialog_h) // 2)

        inner_w = dialog_w - 2

        # Title
        title = "Confirm Dialog"
        title_bar = '─' * ((inner_w - len(title)) // 2) + title + '─' * ((inner_w - len(title) + 1) // 2)

        top = '╭' + title_bar[:inner_w] + '╮'
        try:
            self.stdscr.addstr(dialog_y, dialog_x, top[:dialog_w])
        except curses.error:
            pass

        for i in range(1, dialog_h - 1):
            try:
                self.stdscr.addstr(dialog_y + i, dialog_x, '│')
                self.stdscr.addstr(dialog_y + i, dialog_x + dialog_w - 1, '│')
            except curses.error:
                pass

        try:
            self.stdscr.addstr(dialog_y + dialog_h - 1, dialog_x, '╰' + '─' * inner_w + '╯')
        except curses.error:
            pass

        # Content lines
        lines = [
            "",
            "This action will modify the files in this directory.",
            "         Are you sure you want to continue?",
            "",
            "",
        ]

        for i, line in enumerate(lines):
            try:
                self.stdscr.addstr(dialog_y + 1 + i, dialog_x + 1, 
                                   line[:inner_w].ljust(inner_w))
            except curses.error:
                pass

        # Buttons
        continue_text = "Continue"
        cancel_text = "Cancel"
        buttons_line = f"                   {continue_text}  {cancel_text}"
        try:
            self.stdscr.addstr(dialog_y + 6, dialog_x + 1, buttons_line[:inner_w])
        except curses.error:
            pass

    def draw_notification(self, dims):
        """Draw a notification popup"""
        width = dims['width']
        height = dims['height']

        msg = self.notification
        notif_w = min(len(msg) + 4, width - 10)
        notif_h = 3

        x = max(0, width - notif_w - 5)
        y = height - notif_h - 4

        # Box
        try:
            self.stdscr.addstr(y, x, '╭' + 'Notification' + '─' * (notif_w - 2 - len('Notification')) + '╮')
            self.stdscr.addstr(y + 1, x, '│' + msg[:(notif_w-2)].ljust(notif_w-2) + '│')
            self.stdscr.addstr(y + 2, x, '╰' + '─' * (notif_w - 2) + '╯')
        except curses.error:
            pass

    def position_cursor(self, dims):
        """Position the cursor based on active pane"""
        if self.active_pane == ActivePane.SEARCH:
            cursor_x = min(len(self.search_text), dims['left_width'] - 2)
            try:
                self.stdscr.move(1, 1 + cursor_x)
            except curses.error:
                pass
        elif self.active_pane == ActivePane.REPLACE:
            if self.replace_mode != ReplaceMode.DELETE_LINE:
                cursor_x = min(len(self.replace_text), dims['left_width'] - 2)
            else:
                cursor_x = 0
            y = dims['search_height'] + 1
            try:
                self.stdscr.move(y, 1 + cursor_x)
            except curses.error:
                pass
        else:
            # Move cursor to a non-intrusive position
            try:
                self.stdscr.move(dims['height'] - 1, 0)
            except curses.error:
                pass


def main():
    import argparse

    parser = argparse.ArgumentParser(
        prog='executable',
        description='A simple terminal UI for search and replace, ala VS Code'
    )
    parser.add_argument('-p', '--project-root', default='.', metavar='PATH',
                        help='Path to the project root [default: .]')
    parser.add_argument('-V', '--version', action='store_true',
                        help='Print version')

    args = parser.parse_args()

    if args.version:
        config_dir = Path.home() / '.config' / 'serpl'
        print(f"serpl {VERSION} ({BUILD_DATE})")
        print(f"")
        print(f"Authors: {AUTHOR}")
        print(f"")
