                    if self.in_file_expanded:
                        # Match-level format: indicator + 5-char-number + space
                        indicator = '>' if is_selected else ' '
                        line_no_str = f"{line_no:5d}"
                        prefix = indicator + line_no_str + ' '
                    else:
                        # File-level format: 4-char-number + space
                        line_no_str = f"{line_no:4d}"
                        prefix = line_no_str + ' '

                    prefix_len = len(prefix)
                    max_content = inner_w - prefix_len

                    # Build line with replacement preview
                    if is_match and self.replace_text:
                        # Show match + replacement inline
                        display_content = self.build_match_display(content, submatches, max_content)
                    else:
                        display_content = content

                    if len(display_content) > max_content:
                        display_content = display_content[:max_content]

                    full_line = prefix + display_content.ljust(max_content)

                    try:
