                            # Draw content with highlighting
                            self.draw_match_content(row_y, pos, display_content, 
                                                     submatches, max_content, is_match)
                        elif is_match:
                            self.stdscr.addstr(row_y, x + 1, prefix)
                            pos = x + 1 + prefix_len
                            self.draw_match_content(row_y, pos, display_content,
                                                     submatches, max_content, is_match)
                        else:
                            self.stdscr.addstr(row_y, x + 1, full_line[:inner_w])
                    except curses.error:
