#!/usr/bin/env python3
"""
serpl - A simple terminal UI for search and replace, ala VS Code
"""

import curses
import sys
import os
import re
import json
import subprocess
import signal
import time
from pathlib import Path
from typing import Optional, List, Tuple, Dict, Any
from enum import Enum, auto

VERSION = "0.3.4-"
BUILD_DATE = "2026-04-20"
AUTHOR = "Yassine Bridi <ybridi@gmail.com>"

class SearchMode(Enum):
    SIMPLE = "Simple"
    MATCH_CASE = "Match Case"
    MATCH_WHOLE_WORD = "Match Whole Word"
    MATCH_CASE_WHOLE_WORD = "Match Case Whole Word"
    REGEX = "Regex"

SEARCH_MODES = [
    SearchMode.SIMPLE,
    SearchMode.MATCH_CASE,
    SearchMode.MATCH_WHOLE_WORD,
    SearchMode.MATCH_CASE_WHOLE_WORD,
    SearchMode.REGEX,
]

class ReplaceMode(Enum):
    SIMPLE = "Simple"
    PRESERVE_CASE = "Preserve Case"
    DELETE_LINE = "Delete Line"

REPLACE_MODES = [
    ReplaceMode.SIMPLE,
    ReplaceMode.PRESERVE_CASE,
    ReplaceMode.DELETE_LINE,
]

class ActivePane(Enum):
    SEARCH = auto()
    REPLACE = auto()
    RESULTS = auto()

CONTEXT_LINES = 3

def parse_json5(text):
    """Parse JSON5 (JSON with comments and trailing commas)"""
    text = re.sub(r'//[^\n]*', '', text)
    text = re.sub(r'/\*.*?\*/', '', text, flags=re.DOTALL)
    text = re.sub(r',\s*([}\]])', r'\1', text)
    return json.loads(text)

def load_config():
    config_dir = Path.home() / '.config' / 'serpl'
    config_file = config_dir / 'config.json5'

    default_config = {
        "keybindings": {
            "<Ctrl-d>": "Quit",
            "<Ctrl-c>": "Quit",
            "<Ctrl-z>": "Suspend",
            "<Ctrl-r>": "Refresh",
            "<Tab>": "LoopOverTabs",
            "<Backtab>": "BackLoopOverTabs",
            "<Ctrl-o>": "ProcessReplace",
            "<Ctrl-b>": "ShowHelp",
        }
    }

    if config_file.exists():
        try:
            with open(config_file) as f:
                content = f.read()
            config = parse_json5(content)
            return config
        except:
            pass

    return default_config

class ResultItem:
    def __init__(self, path: str, matches: List[Dict]):
        self.path = path
        self.matches = matches  # {line_number, line_content, submatches: [{start, end}]}

def run_ripgrep(pattern: str, project_root: str, search_mode: SearchMode) -> List[ResultItem]:
    if not pattern:
        return []

    cmd = ['rg', '--json']

    if search_mode == SearchMode.SIMPLE:
        cmd += ['-i', '-F']
    elif search_mode == SearchMode.MATCH_CASE:
        cmd += ['-F']
    elif search_mode == SearchMode.MATCH_WHOLE_WORD:
        cmd += ['-i', '-w', '-F']
    elif search_mode == SearchMode.MATCH_CASE_WHOLE_WORD:
        cmd += ['-w', '-F']
    elif search_mode == SearchMode.REGEX:
        pass  # raw regex

    cmd += [pattern, project_root]

    try:
        result = subprocess.run(cmd, capture_output=True, text=True, timeout=30)
        output = result.stdout
    except:
        return []

    files: Dict[str, ResultItem] = {}
    file_order = []
    current_file = None

    for line in output.splitlines():
        if not line.strip():
            continue
        try:
            data = json.loads(line)
        except:
            continue

        msg_type = data.get('type')

        if msg_type == 'begin':
            path = data['data']['path']['text']
            current_file = path
            if path not in files:
                files[path] = ResultItem(path, [])
                file_order.append(path)

        elif msg_type == 'match' and current_file:
            match_data = data['data']
            line_number = match_data['line_number']
            line_content = match_data['lines']['text'].rstrip('\n')
            submatches = [
                {'start': sm['start'], 'end': sm['end']}
                for sm in match_data['submatches']
            ]
            files[current_file].matches.append({
                'line_number': line_number,
                'line_content': line_content,
                'submatches': submatches,
            })

    return [files[p] for p in file_order]

def preserve_case_replace(original: str, replacement: str) -> str:
    if not original:
        return replacement
    if original.isupper():
        return replacement.upper()
    elif original.islower():
        return replacement.lower()
    elif original[0].isupper():
        if replacement:
            return replacement[0].upper() + replacement[1:].lower()
        return replacement
    return replacement

def apply_replacement_to_line(line: str, submatches: List[Dict], 
                               replacement: str, replace_mode: ReplaceMode) -> Optional[str]:
    if replace_mode == ReplaceMode.DELETE_LINE:
        return None

    result = line
    for sm in reversed(sorted(submatches, key=lambda x: x['start'])):
        start, end = sm['start'], sm['end']
        original_match = line[start:end]

        if replace_mode == ReplaceMode.PRESERVE_CASE:
            actual_replacement = preserve_case_replace(original_match, replacement)
        else:
            actual_replacement = replacement

        result = result[:start] + actual_replacement + result[end:]

    return result

def apply_replacement_to_file(result_item: ResultItem, replacement: str, 
                               replace_mode: ReplaceMode,
                               match_indices: Optional[List[int]] = None) -> bool:
    path = result_item.path

    try:
        with open(path, 'r', encoding='utf-8', errors='replace') as f:
            lines = f.readlines()
    except Exception:
        return False

    # Build mapping of line_number -> list of submatches
    lines_to_modify = {}

    for match_idx, match in enumerate(result_item.matches):
        if match_indices is not None and match_idx not in match_indices:
            continue
        line_no = match['line_number']
        if line_no not in lines_to_modify:
            lines_to_modify[line_no] = []
        lines_to_modify[line_no].extend(match['submatches'])

    if not lines_to_modify:
        return True

    new_lines = []
    for i, line in enumerate(lines):
        line_no = i + 1
        if line_no in lines_to_modify:
            has_newline = line.endswith('\n')
            line_stripped = line.rstrip('\n')

            submatches = lines_to_modify[line_no]
            # Deduplicate
            seen = set()
            unique_submatches = []
            for sm in sorted(submatches, key=lambda x: x['start']):
                key = (sm['start'], sm['end'])
                if key not in seen:
                    seen.add(key)
                    unique_submatches.append(sm)

            result = apply_replacement_to_line(line_stripped, unique_submatches, 
                                                replacement, replace_mode)
            if result is None:
                pass  # Delete line
            else:
                new_lines.append(result + ('\n' if has_newline else ''))
        else:
            new_lines.append(line)

    try:
        with open(path, 'w', encoding='utf-8') as f:
            f.writelines(new_lines)
        return True
    except Exception:
        return False

def get_file_context_groups(result_item: ResultItem) -> List[Dict]:
    path = result_item.path
    try:
        with open(path, 'r', encoding='utf-8', errors='replace') as f:
            all_lines = f.readlines()
    except:
        all_lines = []

    total_lines = len(all_lines)
    matches = result_item.matches

    if not matches:
        return []

    groups = []

    for i, match in enumerate(matches):
        match_line = match['line_number']

        prev_match = matches[i-1]['line_number'] if i > 0 else 0
        next_match = matches[i+1]['line_number'] if i < len(matches) - 1 else total_lines + 1

        start = max(prev_match, match_line - CONTEXT_LINES)
        end = min(next_match - 1, match_line + CONTEXT_LINES)

        start = max(1, start)
        end = min(total_lines, end)

        group_lines = []
        for line_no in range(start, end + 1):
            if line_no <= len(all_lines):
                content = all_lines[line_no - 1].rstrip('\n')
            else:
                content = ''
            is_match = (line_no == match_line)
            group_lines.append({
                'line_number': line_no,
                'content': content,
                'is_match': is_match,
                'submatches': match['submatches'] if is_match else [],
            })

        groups.append({
            'match_idx': i,
            'match_line': match_line,
            'lines': group_lines,
        })

    return groups


def make_panel_title(text: str, mode_label: str, inner_width: int) -> str:
    """Create a panel title string that fills inner_width characters"""
    # Format: text + dashes + mode_label
    dashes = max(0, inner_width - len(text) - len(mode_label))
    title = text + '─' * dashes + mode_label
    if len(title) > inner_width:
        title = title[:inner_width]
    return title


def draw_rounded_box(stdscr, y: int, x: int, height: int, width: int, 
                     title: str = "", attr=curses.A_NORMAL):
    """Draw a rounded box with optional title in the top border"""
    if height < 2 or width < 2:
        return

    inner_w = width - 2

    if title:
        # Title fills the inner width
        if len(title) > inner_w:
            title = title[:inner_w]
        top = '╭' + title.ljust(inner_w, ' ')[:inner_w] + '╮'
        # The title is already formatted to fill inner_w, just use it
        top = '╭' + title + '╮'
    else:
        top = '╭' + '─' * inner_w + '╮'

    try:
        stdscr.addstr(y, x, top[:width], attr)
    except curses.error:
        pass

    for i in range(1, height - 1):
        try:
            stdscr.addstr(y + i, x, '│', attr)
            stdscr.addstr(y + i, x + width - 1, '│', attr)
        except curses.error:
            pass

    bottom = '╰' + '─' * inner_w + '╯'
    try:
        stdscr.addstr(y + height - 1, x, bottom[:width], attr)
    except curses.error:
        pass


class SerplApp:
    def __init__(self, stdscr, project_root: str, config: dict):
        self.stdscr = stdscr
        self.project_root = project_root
        self.config = config

        self.search_text = ""
        self.replace_text = ""
        self.search_mode = SearchMode.SIMPLE
        self.replace_mode = ReplaceMode.SIMPLE
        self.active_pane = ActivePane.SEARCH

        self.results: List[ResultItem] = []
        self.result_selected_idx: Optional[int] = None

        self.in_file_expanded = False
        self.match_selected_idx: Optional[int] = None

        self.show_help = False
        self.help_tab = 0
        self.show_confirm = False
        self.confirm_selected = 0
        self.notification: Optional[str] = None
        self.notification_time: float = 0
        self.NOTIFICATION_DURATION = 3.0

        self.preview_scroll = 0

        # Setup
        curses.start_color()
        curses.use_default_colors()
        curses.init_pair(1, curses.COLOR_YELLOW, -1)
        curses.init_pair(2, curses.COLOR_GREEN, -1)
        curses.init_pair(3, curses.COLOR_RED, -1)
        curses.init_pair(4, curses.COLOR_CYAN, -1)
        curses.init_pair(5, curses.COLOR_WHITE, curses.COLOR_BLUE)
        curses.init_pair(6, curses.COLOR_BLACK, curses.COLOR_WHITE)
        curses.init_pair(7, curses.COLOR_MAGENTA, -1)

        curses.noecho()
        curses.cbreak()
        stdscr.keypad(True)
        curses.curs_set(1)

    def run(self):
        while True:
            self.draw()
            if not self.handle_input():
                break

    def get_dims(self):
        height, width = self.stdscr.getmaxyx()
        left_width = max(int(width * 0.30), 20)
        search_h = 3
        replace_h = 3
        results_h = height - search_h - replace_h - 1
        right_width = width - left_width
        preview_h = height - 1
        return {
            'H': height, 'W': width,
            'LW': left_width, 'RW': right_width,
            'SH': search_h, 'RPH': replace_h,
            'RSH': results_h, 'PH': preview_h,
        }

    def handle_input(self) -> bool:
        try:
            key = self.stdscr.get_wch()
        except curses.error:
            return True

        # Check notification expiry
        if self.notification and time.time() - self.notification_time > self.NOTIFICATION_DURATION:
            self.notification = None

        if self.show_help:
            return self._handle_help(key)

        if self.show_confirm:
            return self._handle_confirm(key)

        # Global keys
        if key == '\x04' or key == '\x03':  # Ctrl-d, Ctrl-c
            return False

        if key == '\x1a':  # Ctrl-z
            curses.def_prog_mode()
            curses.endwin()
            os.kill(os.getpid(), signal.SIGTSTP)
            curses.reset_prog_mode()
            self.stdscr.refresh()
            return True

        if key == '\x12':  # Ctrl-r
            if self.search_text:
                self.do_search()
            return True

        if key == '\x02':  # Ctrl-b
            self.show_help = True
            self.help_tab = 0
            return True

        if key == '\x0f':  # Ctrl-o
            if self.results:
                self.show_confirm = True
                self.confirm_selected = 0
            return True

        if key == '\t':
            self._cycle_pane(True)
            return True

        if isinstance(key, int) and key == curses.KEY_BTAB:
            self._cycle_pane(False)
            return True

        if self.active_pane == ActivePane.SEARCH:
            return self._handle_search(key)
        elif self.active_pane == ActivePane.REPLACE:
            return self._handle_replace(key)
        elif self.active_pane == ActivePane.RESULTS:
            return self._handle_results(key)

        return True

    def _handle_help(self, key) -> bool:
        if key == '\x1b' or key == 'q':
            self.show_help = False
        elif isinstance(key, int) and key == curses.KEY_RIGHT:
            self.help_tab = min(1, self.help_tab + 1)
        elif isinstance(key, int) and key == curses.KEY_LEFT:
            self.help_tab = max(0, self.help_tab - 1)
        elif key == 'l':
            self.help_tab = min(1, self.help_tab + 1)
        elif key == 'h':
            self.help_tab = max(0, self.help_tab - 1)
        return True

    def _handle_confirm(self, key) -> bool:
        if key == '\x1b':
            self.show_confirm = False
        elif isinstance(key, int) and key == curses.KEY_LEFT:
            self.show_confirm = False
        elif key == '\n' or key == '\r':
            self.show_confirm = False
            self.do_replace_all()
        return True

    def _handle_search(self, key) -> bool:
        if key == '\n' or key == '\r':
            if self.search_text:
                self.do_search()
        elif key == '\x0e':  # Ctrl-n
            idx = SEARCH_MODES.index(self.search_mode)
            self.search_mode = SEARCH_MODES[(idx + 1) % len(SEARCH_MODES)]
            if self.search_text:
                self.do_search()
        elif isinstance(key, int) and key in (curses.KEY_BACKSPACE, 263):
            self.search_text = self.search_text[:-1]
        elif key in ('\x7f', '\b'):
            self.search_text = self.search_text[:-1]
        elif isinstance(key, str) and len(key) == 1 and (key.isprintable() or ord(key) >= 128):
            self.search_text += key
        elif isinstance(key, int) and 32 <= key < 256:
            self.search_text += chr(key)
        return True

    def _handle_replace(self, key) -> bool:
        if key == '\x0e':  # Ctrl-n
            idx = REPLACE_MODES.index(self.replace_mode)
            self.replace_mode = REPLACE_MODES[(idx + 1) % len(REPLACE_MODES)]
        elif isinstance(key, int) and key in (curses.KEY_BACKSPACE, 263):
            self.replace_text = self.replace_text[:-1]
        elif key in ('\x7f', '\b'):
            self.replace_text = self.replace_text[:-1]
        elif isinstance(key, str) and len(key) == 1 and (key.isprintable() or ord(key) >= 128):
            self.replace_text += key
        elif isinstance(key, int) and 32 <= key < 256:
            self.replace_text += chr(key)
        return True

    def _handle_results(self, key) -> bool:
        if not self.results:
            return True

        if not self.in_file_expanded:
            return self._handle_file_nav(key)
        else:
            return self._handle_match_nav(key)

    def _nav_down(self, idx, total):
        if idx is None:
            return 0
        return (idx + 1) % total

    def _nav_up(self, idx, total):
        if idx is None:
            return total - 1
        return (idx - 1) % total

    def _handle_file_nav(self, key) -> bool:
        n = len(self.results)

        if key in (curses.KEY_DOWN, 'k') or (isinstance(key, int) and key == curses.KEY_DOWN):
            self.result_selected_idx = self._nav_down(self.result_selected_idx, n)
            self.preview_scroll = 0
        elif isinstance(key, int) and key == curses.KEY_UP:
            self.result_selected_idx = self._nav_up(self.result_selected_idx, n)
            self.preview_scroll = 0
        elif key == 'j':
            self.result_selected_idx = self._nav_down(self.result_selected_idx, n)
            self.preview_scroll = 0
        elif key == 'k':
            self.result_selected_idx = self._nav_up(self.result_selected_idx, n)
            self.preview_scroll = 0
        elif key in ('g', 'h') or (isinstance(key, int) and key == curses.KEY_LEFT):
            self.result_selected_idx = 0
            self.preview_scroll = 0
        elif key in ('G', 'l') or (isinstance(key, int) and key == curses.KEY_RIGHT):
            self.result_selected_idx = n - 1
            self.preview_scroll = 0
        elif key in ('\n', '\r'):
            if self.result_selected_idx is not None:
                self.in_file_expanded = True
                self.match_selected_idx = None
                self.preview_scroll = 0
        elif key == 'd':
            if self.result_selected_idx is not None:
                del self.results[self.result_selected_idx]
                if not self.results:
                    self.result_selected_idx = None
                elif self.result_selected_idx >= len(self.results):
                    self.result_selected_idx = len(self.results) - 1
                self.preview_scroll = 0
        elif key == 'r':
            if self.result_selected_idx is not None:
                self._do_replace_file(self.result_selected_idx)

        return True

    def _handle_match_nav(self, key) -> bool:
        if self.result_selected_idx is None:
            return True

        result = self.results[self.result_selected_idx]
        n = len(result.matches)

        if key in ('\n', '\r'):
            self.in_file_expanded = False
            self.match_selected_idx = None
            self.preview_scroll = 0
        elif key in (curses.KEY_DOWN, 'k') or (isinstance(key, int) and key == curses.KEY_DOWN):
            self.match_selected_idx = self._nav_down(self.match_selected_idx, n)
            self.preview_scroll = 0
        elif isinstance(key, int) and key == curses.KEY_UP:
            self.match_selected_idx = self._nav_up(self.match_selected_idx, n)
            self.preview_scroll = 0
        elif key == 'j':
            self.match_selected_idx = self._nav_down(self.match_selected_idx, n)
            self.preview_scroll = 0
        elif key == 'k':
            self.match_selected_idx = self._nav_up(self.match_selected_idx, n)
            self.preview_scroll = 0
        elif key in ('g', 'h') or (isinstance(key, int) and key == curses.KEY_LEFT):
            self.match_selected_idx = 0
            self.preview_scroll = 0
        elif key in ('G', 'l') or (isinstance(key, int) and key == curses.KEY_RIGHT):
            self.match_selected_idx = n - 1
            self.preview_scroll = 0
        elif key == 'd':
            if self.match_selected_idx is not None:
                del result.matches[self.match_selected_idx]
                if not result.matches:
                    del self.results[self.result_selected_idx]
                    self.in_file_expanded = False
                    self.match_selected_idx = None
                    if self.result_selected_idx is not None and self.result_selected_idx >= len(self.results):
                        self.result_selected_idx = len(self.results) - 1 if self.results else None
                else:
                    if self.match_selected_idx >= len(result.matches):
                        self.match_selected_idx = len(result.matches) - 1
                self.preview_scroll = 0
        elif key == 'r':
            if self.match_selected_idx is not None:
                self._do_replace_match(self.result_selected_idx, self.match_selected_idx)

        return True

    def _cycle_pane(self, forward: bool):
        panes = [ActivePane.SEARCH, ActivePane.REPLACE, ActivePane.RESULTS]
        idx = panes.index(self.active_pane)
        if forward:
            idx = (idx + 1) % 3
        else:
            idx = (idx - 1) % 3
        self.active_pane = panes[idx]

    def do_search(self):
        self.results = run_ripgrep(self.search_text, self.project_root, self.search_mode)
        self.result_selected_idx = None
        self.in_file_expanded = False
        self.match_selected_idx = None
        self.preview_scroll = 0

    def do_replace_all(self):
        for result in self.results[:]:
            apply_replacement_to_file(result, self.replace_text, self.replace_mode)
        if self.search_text:
            self.do_search()

    def _do_replace_file(self, file_idx: int):
        if file_idx >= len(self.results):
            return
        result = self.results[file_idx]
        success = apply_replacement_to_file(result, self.replace_text, self.replace_mode)
        if success:
            self.notification = "File replacement completed successfully"
            self.notification_time = time.time()
            del self.results[file_idx]
            if not self.results:
                self.result_selected_idx = None
            elif self.result_selected_idx is not None and self.result_selected_idx >= len(self.results):
                self.result_selected_idx = len(self.results) - 1

    def _do_replace_match(self, file_idx: int, match_idx: int):
        if file_idx >= len(self.results):
            return
        result = self.results[file_idx]
        if match_idx >= len(result.matches):
            return

        match = result.matches[match_idx]
        path = result.path

        try:
            with open(path, 'r', encoding='utf-8', errors='replace') as f:
                all_lines = f.readlines()
        except:
            return

        line_no = match['line_number']
        if line_no <= len(all_lines):
            line = all_lines[line_no - 1]
            has_newline = line.endswith('\n')
            line_stripped = line.rstrip('\n')

            new_line = apply_replacement_to_line(
                line_stripped, match['submatches'], self.replace_text, self.replace_mode
            )

            if new_line is None:
                all_lines.pop(line_no - 1)
            else:
                all_lines[line_no - 1] = new_line + ('\n' if has_newline else '')

            try:
                with open(path, 'w', encoding='utf-8') as f:
                    f.writelines(all_lines)
            except:
                return

        del result.matches[match_idx]
        if not result.matches:
            del self.results[file_idx]
            self.in_file_expanded = False
            self.match_selected_idx = None
            if self.result_selected_idx is not None and self.result_selected_idx >= len(self.results):
                self.result_selected_idx = len(self.results) - 1 if self.results else None
        else:
            if self.match_selected_idx is not None and self.match_selected_idx >= len(result.matches):
                self.match_selected_idx = len(result.matches) - 1

    def draw(self):
        d = self.get_dims()
        self.stdscr.erase()

        self._draw_search(d)
        self._draw_replace(d)
        self._draw_results(d)
        self._draw_preview(d)
        self._draw_status(d)

        if self.show_help:
            self._draw_help(d)
        elif self.show_confirm:
            self._draw_confirm(d)

        if self.notification and time.time() - self.notification_time < self.NOTIFICATION_DURATION:
            self._draw_notification(d)

        self._position_cursor(d)
        self.stdscr.refresh()

    def _make_panel_title(self, name: str, mode_label: str, inner_w: int) -> str:
        dashes = max(0, inner_w - len(name) - len(mode_label))
        title = name + '─' * dashes + mode_label
        if len(title) > inner_w:
            title = title[:inner_w]
        return title

    def _draw_search(self, d):
        lw = d['LW']
        inner_w = lw - 2
        title = self._make_panel_title("Search", f"[{self.search_mode.value}]", inner_w)
        draw_rounded_box(self.stdscr, 0, 0, 3, lw, title=title)

        text = self.search_text[-inner_w:] if len(self.search_text) > inner_w else self.search_text
        try:
            self.stdscr.addstr(1, 1, text.ljust(inner_w)[:inner_w])
        except curses.error:
            pass

    def _draw_replace(self, d):
        lw = d['LW']
        inner_w = lw - 2
        title = self._make_panel_title("Replace", f"[{self.replace_mode.value}]", inner_w)
        y = d['SH']
        draw_rounded_box(self.stdscr, y, 0, 3, lw, title=title)

        if self.replace_mode == ReplaceMode.DELETE_LINE:
            text = "[Entire line will be deleted]"
        else:
            text = self.replace_text

        text = text[:inner_w]
        try:
            self.stdscr.addstr(y + 1, 1, text.ljust(inner_w)[:inner_w])
        except curses.error:
            pass

    def _draw_results(self, d):
        lw = d['LW']
        y = d['SH'] + d['RPH']
        h = d['RSH']
        inner_w = lw - 2
        inner_h = h - 2

        draw_rounded_box(self.stdscr, y, 0, h, lw, title="Result List")

        for i, result in enumerate(self.results):
            if i >= inner_h:
                break

            rel_path = os.path.relpath(result.path, self.project_root)
            n = len(result.matches)
            text = f"{rel_path} ({n})"
            if len(text) > inner_w:
                text = text[:inner_w]

            is_selected = (i == self.result_selected_idx)
            attr = curses.A_REVERSE if is_selected else curses.A_NORMAL

            try:
                self.stdscr.addstr(y + 1 + i, 1, text.ljust(inner_w)[:inner_w], attr)
            except curses.error:
                pass

    def _build_preview_lines(self) -> List[Dict]:
        """Build the list of display lines for the preview panel"""
        if self.result_selected_idx is None or self.result_selected_idx >= len(self.results):
            return []

        result = self.results[self.result_selected_idx]
        groups = get_file_context_groups(result)

        display_lines = []

        for group in groups:
            for line_info in group['lines']:
                is_selected = (
                    self.in_file_expanded and
                    self.match_selected_idx is not None and
                    group['match_idx'] == self.match_selected_idx and
                    line_info['is_match']
                )
                display_lines.append({
                    'line_number': line_info['line_number'],
                    'content': line_info['content'],
                    'is_match': line_info['is_match'],
                    'submatches': line_info['submatches'],
                    'is_selected': is_selected,
                    'match_idx': group['match_idx'],
                })

            # Separator after group
            display_lines.append({'sep': True})

        return display_lines

    def _draw_preview(self, d):
        lw = d['LW']
        rw = d['RW']
        ph = d['PH']
        x = lw
        inner_w = rw - 2
        inner_h = ph - 2

        # Top border with "Preview" title
        title = 'Preview'
        dashes = inner_w - len(title)
        top_border = '╭' + title + '─' * max(0, dashes) + '╮'
        try:
            self.stdscr.addstr(0, x, top_border[:rw])
        except curses.error:
            pass

        # Side borders
        for row in range(1, ph - 1):
            try:
                self.stdscr.addstr(row, x, '│')
                self.stdscr.addstr(row, x + rw - 1, '│')
            except curses.error:
                pass

        # Bottom border
        try:
            self.stdscr.addstr(ph - 1, x, '╰' + '─' * inner_w + '╯')
        except curses.error:
            pass

        # Get preview content
        preview_lines = self._build_preview_lines()

        # Draw content
        for row_idx in range(inner_h):
            disp = row_idx + self.preview_scroll
            row_y = 1 + row_idx

            if disp >= len(preview_lines):
                break

            line = preview_lines[disp]

            if line.get('sep'):
                # Separator
                if self.in_file_expanded:
                    sep = '  ' + '-' * (inner_w - 2)
                else:
                    sep = '-' * inner_w
                try:
                    self.stdscr.addstr(row_y, x + 1, sep[:inner_w])
                except curses.error:
                    pass
            else:
                line_no = line['line_number']
                content = line['content']
                is_match = line['is_match']
                is_selected = line['is_selected']
                submatches = line['submatches']

                if self.in_file_expanded:
                    indicator = '>' if is_selected else ' '
                    prefix = indicator + f"{line_no:5d} "
                else:
                    prefix = f"{line_no:4d} "

                prefix_len = len(prefix)
                max_content = inner_w - prefix_len

                if max_content <= 0:
                    continue

                # Build content with replacement preview
                if is_match and self.replace_text:
                    disp_content = self._build_match_display(content, submatches, max_content)
                elif is_match and not self.replace_text:
                    disp_content = content
                else:
                    disp_content = content

                try:
                    if is_selected:
                        self.stdscr.addstr(row_y, x + 1, prefix, curses.A_BOLD)
                    else:
                        self.stdscr.addstr(row_y, x + 1, prefix)

                    self._draw_content(row_y, x + 1 + prefix_len, disp_content,
                                       content, submatches, max_content, is_match)
                except curses.error:
                    pass

    def _build_match_display(self, content: str, submatches: List[Dict], max_len: int) -> str:
        if not submatches:
            return content[:max_len]

        result = ''
        prev_end = 0

        for sm in sorted(submatches, key=lambda x: x['start']):
            start, end = sm['start'], sm['end']
            result += content[prev_end:start]
            result += content[start:end]
            result += self.replace_text
            prev_end = end

        result += content[prev_end:]
        return result[:max_len]

    def _draw_content(self, y: int, x: int, display_content: str, 
                      original_content: str, submatches: List[Dict], 
                      max_len: int, is_match: bool):
        """Draw content with color highlights for matches"""
        if not is_match:
            try:
                self.stdscr.addstr(y, x, display_content[:max_len].ljust(max_len))
            except curses.error:
                pass
            return

        # Draw with colors
        screen_x = x
        limit = x + max_len

        # We need to interleave original content with replacement
        pos = 0

        for sm in sorted(submatches, key=lambda s: s['start']):
            start, end = sm['start'], sm['end']

            # Text before match
            before = original_content[pos:start]
            if before and screen_x < limit:
                rem = limit - screen_x
                try:
                    self.stdscr.addstr(y, screen_x, before[:rem])
                except curses.error:
                    pass
                screen_x += min(len(before), rem)

            if screen_x >= limit:
                return

            # Match text (highlighted)
            match_text = original_content[start:end]
            if match_text and screen_x < limit:
                rem = limit - screen_x
                try:
                    self.stdscr.addstr(y, screen_x, match_text[:rem],
                                       curses.color_pair(1) | curses.A_BOLD)
                except curses.error:
                    pass
                screen_x += min(len(match_text), rem)

            if screen_x >= limit:
                return

            # Replacement text (green)
            if self.replace_text and screen_x < limit:
                rem = limit - screen_x
                try:
                    self.stdscr.addstr(y, screen_x, self.replace_text[:rem],
                                       curses.color_pair(2) | curses.A_BOLD)
                except curses.error:
                    pass
                screen_x += min(len(self.replace_text), rem)

            pos = end

        # Remaining content after last match
        after = original_content[pos:]
        if after and screen_x < limit:
            rem = limit - screen_x
            try:
                self.stdscr.addstr(y, screen_x, after[:rem])
            except curses.error:
                pass
            screen_x += min(len(after), rem)

        # Pad remaining space
        if screen_x < limit:
            try:
                self.stdscr.addstr(y, screen_x, ' ' * (limit - screen_x))
            except curses.error:
                pass

    def _draw_status(self, d):
        H, W = d['H'], d['W']
        status = self._get_status(W)
        try:
            self.stdscr.addstr(H - 1, 0, status[:W])
        except curses.error:
            pass

    def _get_status(self, width: int) -> str:
        if self.show_help:
            s = "Close Help: <Esc> | Next Tab: <Right> | Previous Tab:"
            if width >= 80:
                s += " <Left>"
            return s

        if self.show_confirm:
            return "Confirm Replace: <Enter> | Cancel Replace: <Esc>, Left:"

        if self.active_pane == ActivePane.SEARCH:
            s = "Help: <Ctrl-b> | Search: <Enter> | Toggle search mode:"
            if width >= 100:
                s += " <Ctrl-n>"
            return s

        if self.active_pane == ActivePane.REPLACE:
            s = "Help: <Ctrl-b> | Replace: <C-o> | Toggle replace mode:"
            if width >= 100:
                s += " <Ctrl-n>"
            return s

        if self.active_pane == ActivePane.RESULTS:
            if self.in_file_expanded:
                s = "Help: <Ctrl-b> | Back to list: <Enter> | Replace Line:"
                if width >= 100:
                    s += " <r>"
                return s
            else:
                return "Help: <Ctrl-b> | Open File: <Enter> | Replace File: <r>"

        return ""

    def _draw_help(self, d):
        H, W = d['H'], d['W']

        dw = min(W, 82)  # Dialog width
        dh = 18
        dy = 4
        dx = 0
        inner_w = dw - 2

        # Clear area
        for i in range(dh):
            try:
                self.stdscr.addstr(dy + i, dx, ' ' * dw)
            except curses.error:
                pass

        # Build title line
        tabs = "[1] Global ─ [2] Navigation"
        close = "Press 'q' to close"
        mid = inner_w - len(tabs) - len(close) - 2
        title_content = " " + tabs + " " + '─' * max(0, mid) + close
        if len(title_content) > inner_w:
            title_content = title_content[:inner_w]

        try:
            self.stdscr.addstr(dy, dx, '╭' + title_content + '╮')
        except curses.error:
            pass

        for i in range(1, dh - 1):
            try:
                self.stdscr.addstr(dy + i, dx, '│')
                self.stdscr.addstr(dy + i, dx + dw - 1, '│')
            except curses.error:
                pass

        try:
            self.stdscr.addstr(dy + dh - 1, dx, '╰' + '─' * inner_w + '╯')
        except curses.error:
            pass

        if self.help_tab == 0:
            lines = [
                "",
                "- Ctrl-c: Quit",
                "- Ctrl-d: Quit",
                "- Ctrl-b: Help dialog",
                "- Ctrl-o: Process Replace For All Files",
                "- Ctrl-n: Loop through search and replace modes",
                "- Enter: Select/Deselect file",
                "- d: delete file/delete line from the replace process",
                "- r: Replace Selected File Or Line",
                "",
            ]
        else:
            lines = [
                "",
                "- Tab: Loop through panes",
                "- j/UpArrow: Move up",
                "- k/DownArrow: Move down",
                "- h/g/LeftArrow: Move to Top",
                "- l/G/RightArrow: Move to Bottom",
                "",
            ]

        for i, line in enumerate(lines):
            if 1 + i >= dh - 1:
                break
            try:
                self.stdscr.addstr(dy + 1 + i, dx + 1, line[:inner_w].ljust(inner_w))
            except curses.error:
                pass

    def _draw_confirm(self, d):
        H, W = d['H'], d['W']

        dw = min(56, W - 4)
        dh = 8
        inner_w = dw - 2

        # Position the dialog to overlap the result list area
        dx = max(0, (W - dw) // 2 - 5)
        dy = 7  # Roughly in middle of result list

        title = "Confirm Dialog"
        pad_left = (inner_w - len(title)) // 2
        pad_right = inner_w - len(title) - pad_left
        title_bar = '─' * pad_left + title + '─' * pad_right

        try:
            self.stdscr.addstr(dy, dx, '╭' + title_bar[:inner_w] + '╮')
        except curses.error:
            pass

        for i in range(1, dh - 1):
            try:
                self.stdscr.addstr(dy + i, dx, '│')
                self.stdscr.addstr(dy + i, dx + dw - 1, '│')
            except curses.error:
                pass

        try:
            self.stdscr.addstr(dy + dh - 1, dx, '╰' + '─' * inner_w + '╯')
        except curses.error:
            pass

        content_lines = [
            "",
            " This action will modify the files in this directory.",
            "          Are you sure you want to continue?",
            "",
            "",
            "                   Continue  Cancel",
        ]

        for i, line in enumerate(content_lines):
            if 1 + i >= dh - 1:
                break
            try:
                self.stdscr.addstr(dy + 1 + i, dx + 1, line[:inner_w].ljust(inner_w))
            except curses.error:
                pass

    def _draw_notification(self, d):
        H, W = d['H'], d['W']
        msg = self.notification or ""
        nw = min(len(msg) + 4, W - 10)
        nh = 3
        nx = max(0, W - nw - 5)
        ny = H - nh - 4

        title = "Notification"
        inner_w = nw - 2
        title_bar = title + '─' * max(0, inner_w - len(title))

        try:
            self.stdscr.addstr(ny, nx, '╭' + title_bar[:inner_w] + '╮')
            self.stdscr.addstr(ny + 1, nx, '│' + msg[:inner_w].ljust(inner_w) + '│')
            self.stdscr.addstr(ny + 2, nx, '╰' + '─' * inner_w + '╯')
        except curses.error:
            pass

    def _position_cursor(self, d):
        if self.active_pane == ActivePane.SEARCH:
            cx = min(len(self.search_text), d['LW'] - 2)
            try:
                self.stdscr.move(1, 1 + cx)
            except curses.error:
                pass
        elif self.active_pane == ActivePane.REPLACE:
            if self.replace_mode != ReplaceMode.DELETE_LINE:
                cx = min(len(self.replace_text), d['LW'] - 2)
            else:
                cx = 0
            try:
                self.stdscr.move(d['SH'] + 1, 1 + cx)
            except curses.error:
                pass
        else:
            try:
                self.stdscr.move(d['H'] - 1, 0)
            except curses.error:
                pass


def main():
