#!/usr/bin/env python3
"""
serpl - A simple terminal UI for search and replace, ala VS Code
"""

import curses
import sys
import os
import re
import json
import subprocess
import signal
import time
from pathlib import Path
from typing import Optional, List, Tuple, Dict
from enum import Enum, auto

VERSION = "0.3.4-"
BUILD_DATE = "2026-04-20"
AUTHOR = "Yassine Bridi <ybridi@gmail.com>"

class SearchMode(Enum):
    SIMPLE = "Simple"
    MATCH_CASE = "Match Case"
    MATCH_WHOLE_WORD = "Match Whole Word"
    MATCH_CASE_WHOLE_WORD = "Match Case Whole Word"
    REGEX = "Regex"

SEARCH_MODES = [
    SearchMode.SIMPLE, SearchMode.MATCH_CASE, SearchMode.MATCH_WHOLE_WORD,
    SearchMode.MATCH_CASE_WHOLE_WORD, SearchMode.REGEX,
]

class ReplaceMode(Enum):
    SIMPLE = "Simple"
    PRESERVE_CASE = "Preserve Case"
    DELETE_LINE = "Delete Line"

REPLACE_MODES = [ReplaceMode.SIMPLE, ReplaceMode.PRESERVE_CASE, ReplaceMode.DELETE_LINE]

class ActivePane(Enum):
    SEARCH = auto()
    REPLACE = auto()
    RESULTS = auto()

CONTEXT_LINES = 3


def parse_json5(text):
    text = re.sub(r'//[^\n]*', '', text)
    text = re.sub(r'/\*.*?\*/', '', text, flags=re.DOTALL)
    text = re.sub(r',\s*([}\]])', r'\1', text)
    return json.loads(text)


def load_config():
    config_dir = Path.home() / '.config' / 'serpl'
    config_file = config_dir / 'config.json5'
    default = {"keybindings": {
        "<Ctrl-d>": "Quit", "<Ctrl-c>": "Quit", "<Ctrl-z>": "Suspend",
        "<Ctrl-r>": "Refresh", "<Tab>": "LoopOverTabs", "<Backtab>": "BackLoopOverTabs",
        "<Ctrl-o>": "ProcessReplace", "<Ctrl-b>": "ShowHelp",
    }}
    if config_file.exists():
        try:
            with open(config_file) as f:
                return parse_json5(f.read())
        except:
            pass
    return default


class ResultItem:
    def __init__(self, path: str, matches: List[Dict]):
        self.path = path
        self.matches = matches  # [{line_number, line_content, submatches: [{start, end}]}]


def run_ripgrep(pattern: str, project_root: str, search_mode: SearchMode) -> List[ResultItem]:
    if not pattern:
        return []
    cmd = ['rg', '--json']
    if search_mode == SearchMode.SIMPLE:
        cmd += ['-i', '-F']
    elif search_mode == SearchMode.MATCH_CASE:
        cmd += ['-F']
    elif search_mode == SearchMode.MATCH_WHOLE_WORD:
        cmd += ['-i', '-w', '-F']
    elif search_mode == SearchMode.MATCH_CASE_WHOLE_WORD:
        cmd += ['-w', '-F']
    # REGEX: no extra flags
    cmd += [pattern, project_root]
    try:
        result = subprocess.run(cmd, capture_output=True, text=True, timeout=30)
    except:
        return []
    files: Dict[str, ResultItem] = {}
    file_order = []
    current_file = None
    for line in result.stdout.splitlines():
        if not line.strip():
            continue
        try:
            data = json.loads(line)
        except:
            continue
        t = data.get('type')
        if t == 'begin':
            path = data['data']['path']['text']
            current_file = path
            if path not in files:
                files[path] = ResultItem(path, [])
                file_order.append(path)
        elif t == 'match' and current_file:
            d = data['data']
            files[current_file].matches.append({
                'line_number': d['line_number'],
                'line_content': d['lines']['text'].rstrip('\n'),
                'submatches': [{'start': sm['start'], 'end': sm['end']} for sm in d['submatches']],
            })
    return [files[p] for p in file_order]


def preserve_case_replace(original: str, replacement: str) -> str:
    if not original:
        return replacement
    if original.isupper():
        return replacement.upper()
    elif original.islower():
        return replacement.lower()
    elif original[0].isupper():
        return (replacement[0].upper() + replacement[1:].lower()) if replacement else replacement
    return replacement


def apply_replacement_to_line(line: str, submatches: List[Dict],
                               replacement: str, replace_mode: ReplaceMode) -> Optional[str]:
    if replace_mode == ReplaceMode.DELETE_LINE:
        return None
    result = line
    for sm in reversed(sorted(submatches, key=lambda x: x['start'])):
        start, end = sm['start'], sm['end']
        if replace_mode == ReplaceMode.PRESERVE_CASE:
            actual = preserve_case_replace(line[start:end], replacement)
        else:
            actual = replacement
        result = result[:start] + actual + result[end:]
    return result


def apply_replacement_to_file(result_item: ResultItem, replacement: str,
                               replace_mode: ReplaceMode,
                               match_indices: Optional[List[int]] = None) -> bool:
    path = result_item.path
    try:
        with open(path, 'r', encoding='utf-8', errors='replace') as f:
            lines = f.readlines()
    except:
        return False
    lines_to_modify: Dict[int, List] = {}
    for idx, match in enumerate(result_item.matches):
        if match_indices is not None and idx not in match_indices:
            continue
        ln = match['line_number']
        if ln not in lines_to_modify:
            lines_to_modify[ln] = []
        lines_to_modify[ln].extend(match['submatches'])
    if not lines_to_modify:
        return True
    new_lines = []
    for i, line in enumerate(lines):
        ln = i + 1
        if ln in lines_to_modify:
            has_nl = line.endswith('\n')
            stripped = line.rstrip('\n')
            seen, sms = set(), []
            for sm in sorted(lines_to_modify[ln], key=lambda x: x['start']):
                k = (sm['start'], sm['end'])
                if k not in seen:
                    seen.add(k)
                    sms.append(sm)
            result = apply_replacement_to_line(stripped, sms, replacement, replace_mode)
            if result is not None:
                new_lines.append(result + ('\n' if has_nl else ''))
        else:
            new_lines.append(line)
    try:
        with open(path, 'w', encoding='utf-8') as f:
            f.writelines(new_lines)
        return True
    except:
        return False


def get_file_context_groups(result_item: ResultItem) -> List[Dict]:
    path = result_item.path
    try:
        with open(path, 'r', encoding='utf-8', errors='replace') as f:
            all_lines = f.readlines()
    except:
        all_lines = []
    total = len(all_lines)
    matches = result_item.matches
    if not matches:
        return []
    groups = []
    for i, match in enumerate(matches):
        ml = match['line_number']
        prev = matches[i-1]['line_number'] if i > 0 else 0
        nxt = matches[i+1]['line_number'] if i < len(matches)-1 else total+1
        start = max(1, max(prev, ml - CONTEXT_LINES))
        end = min(total, min(nxt - 1, ml + CONTEXT_LINES))
        group_lines = []
        for ln in range(start, end+1):
            content = all_lines[ln-1].rstrip('\n') if ln <= len(all_lines) else ''
            is_match = (ln == ml)
            group_lines.append({
                'line_number': ln, 'content': content, 'is_match': is_match,
                'submatches': match['submatches'] if is_match else [],
            })
        groups.append({'match_idx': i, 'match_line': ml, 'lines': group_lines})
    return groups


def build_status_bar(hints, rw: int) -> str:
    """Build status bar from list of (label, key) pairs, fitting in rw chars."""
    current = ""
    for label, key in hints:
        sep = " | " if current else ""
        full = sep + label + (" " + key if key else "")
        short = sep + label
        just_sep = sep
        if len(current) + len(full) <= rw:
            current += full
        elif len(current) + len(short) <= rw:
            current += short
            break
        elif just_sep and len(current) + len(just_sep) <= rw:
            current += just_sep
            break
        else:
            break
    return current


def build_confirm_status(rw: int) -> str:
    """Build confirm dialog status bar."""
    base = "Confirm Replace: <Enter> | Cancel Replace: <Esc>"
    current = base
    sub_hints = [("Left:", "<h>"), ("Right:", "<l>"), ("Loop:", "<Tab>")]
    for label, key in sub_hints:
        full = ", " + label + " " + key
        short = ", " + label
        just_comma = ","
        if len(current) + len(full) <= rw:
            current += full
        elif len(current) + len(short) <= rw:
            current += short
            break
        elif len(current) + len(just_comma) <= rw:
            current += just_comma
            break
        else:
            break
    return current


def addstr(stdscr, y, x, text, attr=curses.A_NORMAL):
    try:
        stdscr.addstr(y, x, text, attr)
    except curses.error:
        pass


def draw_box(stdscr, y, x, h, w, title=""):
    """Draw rounded box. Title fills inner_w."""
    if h < 2 or w < 2:
        return
    inner_w = w - 2
    if title:
        if len(title) < inner_w:
            title = title + '─' * (inner_w - len(title))
        elif len(title) > inner_w:
            title = title[:inner_w]
        top = '╭' + title + '╮'
    else:
        top = '╭' + '─' * inner_w + '╮'
    addstr(stdscr, y, x, top[:w])
    for i in range(1, h-1):
        addstr(stdscr, y+i, x, '│')
        addstr(stdscr, y+i, x+w-1, '│')
    addstr(stdscr, y+h-1, x, '╰' + '─' * inner_w + '╯')


def make_title(name, mode_label, inner_w):
    dashes = max(0, inner_w - len(name) - len(mode_label))
    title = name + '─' * dashes + mode_label
    return title[:inner_w] if len(title) > inner_w else title


class SerplApp:
    def __init__(self, stdscr, project_root: str, config: dict):
        self.stdscr = stdscr
        self.project_root = project_root
        self.config = config
        self.search_text = ""
        self.replace_text = ""
        self.search_mode = SearchMode.SIMPLE
        self.replace_mode = ReplaceMode.SIMPLE
        self.active_pane = ActivePane.SEARCH
        self.results: List[ResultItem] = []
        self.result_selected_idx: Optional[int] = None
        self.in_file_expanded = False
        self.match_selected_idx: Optional[int] = None
        self.show_help = False
        self.help_tab = 0
        self.show_confirm = False
        self.notification: Optional[str] = None
        self.notification_time: float = 0
        self.NOTIFICATION_DURATION = 3.0
        self.preview_scroll = 0

        curses.start_color()
        curses.use_default_colors()
        curses.init_pair(1, curses.COLOR_YELLOW, -1)
        curses.init_pair(2, curses.COLOR_GREEN, -1)
        curses.noecho()
        curses.cbreak()
        stdscr.keypad(True)
        curses.curs_set(1)

    def run(self):
        while True:
            self.draw()
            if not self.handle_input():
                break

    def dims(self):
        H, W = self.stdscr.getmaxyx()
        LW = max(int(W * 0.30), 20)
        return dict(H=H, W=W, LW=LW, RW=W-LW, SH=3, RPH=3, RSH=H-7, PH=H-1)

    def handle_input(self):
        try:
            key = self.stdscr.get_wch()
        except curses.error:
            return True
        if self.notification and time.time() - self.notification_time > self.NOTIFICATION_DURATION:
            self.notification = None
        if self.show_help:
            return self._help_key(key)
        if self.show_confirm:
            return self._confirm_key(key)
        # Global
        if key in ('\x04', '\x03'):
            return False
        if key == '\x1a':
            curses.def_prog_mode(); curses.endwin()
            os.kill(os.getpid(), signal.SIGTSTP)
            curses.reset_prog_mode(); self.stdscr.refresh()
            return True
        if key == '\x12':
            if self.search_text: self.do_search()
            return True
        if key == '\x02':
            self.show_help = True; self.help_tab = 0; return True
        if key == '\x0f':
            if self.results: self.show_confirm = True
            return True
        if key == '\t':
            self._cycle(True); return True
        if isinstance(key, int) and key == curses.KEY_BTAB:
            self._cycle(False); return True
        if self.active_pane == ActivePane.SEARCH:
            return self._search_key(key)
        if self.active_pane == ActivePane.REPLACE:
            return self._replace_key(key)
        if self.active_pane == ActivePane.RESULTS:
            return self._results_key(key)
        return True

    def _help_key(self, key):
        if key in ('\x1b', 'q'):
            self.show_help = False
        elif isinstance(key, int) and key == curses.KEY_RIGHT:
            self.help_tab = min(1, self.help_tab + 1)
        elif isinstance(key, int) and key == curses.KEY_LEFT:
            self.help_tab = max(0, self.help_tab - 1)
        return True

    def _confirm_key(self, key):
        if key == '\x1b':
            self.show_confirm = False
        elif isinstance(key, int) and key == curses.KEY_LEFT:
            self.show_confirm = False
        elif key in ('\n', '\r'):
            self.show_confirm = False
            self.do_replace_all()
        return True

    def _search_key(self, key):
        if key in ('\n', '\r'):
            if self.search_text: self.do_search()
        elif key == '\x0e':
            idx = SEARCH_MODES.index(self.search_mode)
            self.search_mode = SEARCH_MODES[(idx+1) % len(SEARCH_MODES)]
            if self.search_text: self.do_search()
        elif isinstance(key, int) and key in (curses.KEY_BACKSPACE, 263):
            self.search_text = self.search_text[:-1]
        elif key in ('\x7f', '\b'):
            self.search_text = self.search_text[:-1]
        elif isinstance(key, str) and len(key) == 1 and ord(key) >= 32:
            self.search_text += key
        elif isinstance(key, int) and 32 <= key < 256:
            self.search_text += chr(key)
        return True

    def _replace_key(self, key):
        if key == '\x0e':
            idx = REPLACE_MODES.index(self.replace_mode)
            self.replace_mode = REPLACE_MODES[(idx+1) % len(REPLACE_MODES)]
        elif isinstance(key, int) and key in (curses.KEY_BACKSPACE, 263):
            self.replace_text = self.replace_text[:-1]
        elif key in ('\x7f', '\b'):
            self.replace_text = self.replace_text[:-1]
        elif isinstance(key, str) and len(key) == 1 and ord(key) >= 32:
            self.replace_text += key
        elif isinstance(key, int) and 32 <= key < 256:
            self.replace_text += chr(key)
        return True

    def _results_key(self, key):
        if not self.results: return True
        if not self.in_file_expanded:
            return self._file_nav(key)
        return self._match_nav(key)

    def _ndown(self, idx, n): return 0 if idx is None else (idx+1) % n
    def _nup(self, idx, n): return n-1 if idx is None else (idx-1) % n

    def _file_nav(self, key):
        n = len(self.results)
        if isinstance(key, int) and key == curses.KEY_DOWN:
            self.result_selected_idx = self._ndown(self.result_selected_idx, n)
            self.preview_scroll = 0
        elif isinstance(key, int) and key == curses.KEY_UP:
            self.result_selected_idx = self._nup(self.result_selected_idx, n)
            self.preview_scroll = 0
        elif key == 'j':
            self.result_selected_idx = self._ndown(self.result_selected_idx, n)
            self.preview_scroll = 0
        elif key == 'k':
            self.result_selected_idx = self._nup(self.result_selected_idx, n)
            self.preview_scroll = 0
        elif key in ('g', 'h') or (isinstance(key, int) and key == curses.KEY_LEFT):
            self.result_selected_idx = 0; self.preview_scroll = 0
        elif key in ('G', 'l') or (isinstance(key, int) and key == curses.KEY_RIGHT):
            self.result_selected_idx = n-1; self.preview_scroll = 0
        elif key in ('\n', '\r'):
            if self.result_selected_idx is not None:
                self.in_file_expanded = True; self.match_selected_idx = None; self.preview_scroll = 0
        elif key == 'd':
            if self.result_selected_idx is not None:
                del self.results[self.result_selected_idx]
                if not self.results: self.result_selected_idx = None
                elif self.result_selected_idx >= len(self.results): self.result_selected_idx = len(self.results)-1
                self.preview_scroll = 0
        elif key == 'r':
            if self.result_selected_idx is not None:
                self._do_replace_file(self.result_selected_idx)
        return True

    def _match_nav(self, key):
        if self.result_selected_idx is None: return True
        result = self.results[self.result_selected_idx]
        n = len(result.matches)
        if key in ('\n', '\r'):
            self.in_file_expanded = False; self.match_selected_idx = None; self.preview_scroll = 0
        elif isinstance(key, int) and key == curses.KEY_DOWN:
            self.match_selected_idx = self._ndown(self.match_selected_idx, n); self.preview_scroll = 0
        elif isinstance(key, int) and key == curses.KEY_UP:
            self.match_selected_idx = self._nup(self.match_selected_idx, n); self.preview_scroll = 0
        elif key == 'j':
            self.match_selected_idx = self._ndown(self.match_selected_idx, n); self.preview_scroll = 0
        elif key == 'k':
            self.match_selected_idx = self._nup(self.match_selected_idx, n); self.preview_scroll = 0
        elif key in ('g', 'h') or (isinstance(key, int) and key == curses.KEY_LEFT):
            self.match_selected_idx = 0; self.preview_scroll = 0
        elif key in ('G', 'l') or (isinstance(key, int) and key == curses.KEY_RIGHT):
            self.match_selected_idx = n-1; self.preview_scroll = 0
        elif key == 'd':
            if self.match_selected_idx is not None:
                del result.matches[self.match_selected_idx]
                if not result.matches:
                    del self.results[self.result_selected_idx]
                    self.in_file_expanded = False; self.match_selected_idx = None
                    if self.result_selected_idx is not None and self.result_selected_idx >= len(self.results):
                        self.result_selected_idx = len(self.results)-1 if self.results else None
                else:
                    if self.match_selected_idx >= len(result.matches):
                        self.match_selected_idx = len(result.matches)-1
                self.preview_scroll = 0
        elif key == 'r':
            if self.match_selected_idx is not None:
                self._do_replace_match(self.result_selected_idx, self.match_selected_idx)
        return True

    def _cycle(self, forward):
        panes = [ActivePane.SEARCH, ActivePane.REPLACE, ActivePane.RESULTS]
        idx = panes.index(self.active_pane)
        self.active_pane = panes[(idx + (1 if forward else -1)) % 3]

    def do_search(self):
        self.results = run_ripgrep(self.search_text, self.project_root, self.search_mode)
        self.result_selected_idx = None; self.in_file_expanded = False
        self.match_selected_idx = None; self.preview_scroll = 0

    def do_replace_all(self):
        for r in self.results[:]:
            apply_replacement_to_file(r, self.replace_text, self.replace_mode)
        if self.search_text: self.do_search()

    def _do_replace_file(self, idx):
        if idx >= len(self.results): return
        r = self.results[idx]
        if apply_replacement_to_file(r, self.replace_text, self.replace_mode):
            self.notification = "File replacement completed successfully"
            self.notification_time = time.time()
            del self.results[idx]
            if not self.results: self.result_selected_idx = None
            elif self.result_selected_idx is not None and self.result_selected_idx >= len(self.results):
                self.result_selected_idx = len(self.results)-1

    def _do_replace_match(self, file_idx, match_idx):
        if file_idx >= len(self.results): return
        r = self.results[file_idx]
        if match_idx >= len(r.matches): return
        match = r.matches[match_idx]
        path = r.path
        try:
            with open(path, 'r', encoding='utf-8', errors='replace') as f:
                all_lines = f.readlines()
        except: return
        ln = match['line_number']
        if ln <= len(all_lines):
            line = all_lines[ln-1]
            has_nl = line.endswith('\n')
            new_line = apply_replacement_to_line(line.rstrip('\n'), match['submatches'],
                                                  self.replace_text, self.replace_mode)
            if new_line is None:
                all_lines.pop(ln-1)
            else:
                all_lines[ln-1] = new_line + ('\n' if has_nl else '')
            try:
                with open(path, 'w', encoding='utf-8') as f:
                    f.writelines(all_lines)
            except: return
        del r.matches[match_idx]
        if not r.matches:
            del self.results[file_idx]
            self.in_file_expanded = False; self.match_selected_idx = None
            if self.result_selected_idx is not None and self.result_selected_idx >= len(self.results):
                self.result_selected_idx = len(self.results)-1 if self.results else None
        elif self.match_selected_idx is not None and self.match_selected_idx >= len(r.matches):
            self.match_selected_idx = len(r.matches)-1

    def draw(self):
        d = self.dims()
        self.stdscr.erase()
        self._draw_search(d)
        self._draw_replace(d)
        self._draw_results(d)
        self._draw_preview(d)
        self._draw_status(d)
        if self.show_help:
            self._draw_help(d)
        elif self.show_confirm:
            self._draw_confirm(d)
        if self.notification and time.time() - self.notification_time < self.NOTIFICATION_DURATION:
            self._draw_notif(d)
        self._cursor(d)
        self.stdscr.refresh()

    def _draw_search(self, d):
        lw = d['LW']
        iw = lw - 2
        title = make_title("Search", f"[{self.search_mode.value}]", iw)
        draw_box(self.stdscr, 0, 0, 3, lw, title=title)
        text = self.search_text[-iw:] if len(self.search_text) > iw else self.search_text
        addstr(self.stdscr, 1, 1, text.ljust(iw)[:iw])

    def _draw_replace(self, d):
        lw = d['LW']
        iw = lw - 2
        y = d['SH']
        title = make_title("Replace", f"[{self.replace_mode.value}]", iw)
        draw_box(self.stdscr, y, 0, 3, lw, title=title)
        if self.replace_mode == ReplaceMode.DELETE_LINE:
            text = "[Entire line will be deleted]"
        else:
            text = self.replace_text
        addstr(self.stdscr, y+1, 1, text[:iw].ljust(iw)[:iw])

    def _draw_results(self, d):
        lw = d['LW']
        y = d['SH'] + d['RPH']
        h = d['RSH']
        iw = lw - 2
        draw_box(self.stdscr, y, 0, h, lw, title="Result List")
        for i, r in enumerate(self.results):
            if i >= h-2: break
            rel = os.path.relpath(r.path, self.project_root)
            text = f"{rel} ({len(r.matches)})"[:iw]
            attr = curses.A_REVERSE if i == self.result_selected_idx else curses.A_NORMAL
            addstr(self.stdscr, y+1+i, 1, text.ljust(iw)[:iw], attr)

    def _preview_lines(self):
        if self.result_selected_idx is None or self.result_selected_idx >= len(self.results):
            return []
        r = self.results[self.result_selected_idx]
        groups = get_file_context_groups(r)
        lines = []
        for g in groups:
            for li in g['lines']:
                is_sel = (self.in_file_expanded and self.match_selected_idx is not None
                          and g['match_idx'] == self.match_selected_idx and li['is_match'])
                lines.append({
                    'ln': li['line_number'], 'content': li['content'],
                    'is_match': li['is_match'], 'sms': li['submatches'],
                    'is_sel': is_sel, 'midx': g['match_idx'],
                })
            lines.append({'sep': True})
        return lines

    def _draw_preview(self, d):
        lw, rw, ph = d['LW'], d['RW'], d['PH']
        x = lw
        iw = rw - 2
        ih = ph - 2
        title = 'Preview'
        addstr(self.stdscr, 0, x, '╭' + title + '─' * max(0, iw-len(title)) + '╮')
        for row in range(1, ph-1):
            addstr(self.stdscr, row, x, '│')
            addstr(self.stdscr, row, x+rw-1, '│')
        addstr(self.stdscr, ph-1, x, '╰' + '─' * iw + '╯')

        plines = self._preview_lines()
        for ri in range(ih):
            di = ri + self.preview_scroll
            ry = 1 + ri
            if di >= len(plines): break
            pl = plines[di]
            if pl.get('sep'):
                sep = ('  ' + '-' * (iw-2)) if self.in_file_expanded else ('-' * iw)
                addstr(self.stdscr, ry, x+1, sep[:iw])
            else:
                ln = pl['ln']
                content = pl['content']
                is_match = pl['is_match']
                is_sel = pl['is_sel']
                sms = pl['sms']
                if self.in_file_expanded:
                    prefix = ('>' if is_sel else ' ') + f"{ln:5d} "
                else:
                    prefix = f"{ln:4d} "
                plen = len(prefix)
                mc = iw - plen
                if mc <= 0: continue
                addstr(self.stdscr, ry, x+1, prefix, curses.A_BOLD if is_sel else curses.A_NORMAL)
                self._draw_content(ry, x+1+plen, content, sms, mc, is_match)

    def _draw_content(self, y, x, content, sms, max_len, is_match):
        if not is_match or not sms:
            addstr(self.stdscr, y, x, content[:max_len].ljust(max_len))
            return
        sx = x
        lim = x + max_len
        pos = 0
        for sm in sorted(sms, key=lambda s: s['start']):
            st, en = sm['start'], sm['end']
            before = content[pos:st]
            if before and sx < lim:
                r = lim - sx
                addstr(self.stdscr, y, sx, before[:r])
                sx += min(len(before), r)
            if sx >= lim: return
            mtxt = content[st:en]
            if mtxt and sx < lim:
                r = lim - sx
                addstr(self.stdscr, y, sx, mtxt[:r], curses.color_pair(1) | curses.A_BOLD)
                sx += min(len(mtxt), r)
            if sx >= lim: return
            if self.replace_text and sx < lim:
                r = lim - sx
                addstr(self.stdscr, y, sx, self.replace_text[:r], curses.color_pair(2) | curses.A_BOLD)
                sx += min(len(self.replace_text), r)
            pos = en
        after = content[pos:]
        if after and sx < lim:
            r = lim - sx
            addstr(self.stdscr, y, sx, after[:r])
            sx += min(len(after), r)
        if sx < lim:
            addstr(self.stdscr, y, sx, ' ' * (lim - sx))

    def _draw_status(self, d):
        H, W, LW = d['H'], d['W'], d['LW']
        RW = W - LW

        if self.show_help:
            hints = [("Close Help:", "<Esc>"), ("Next Tab:", "<Right>"), ("Previous Tab:", "<Left>")]
            status = build_status_bar(hints, RW)
        elif self.show_confirm:
            status = build_confirm_status(RW)
        elif self.active_pane == ActivePane.SEARCH:
            hints = [("Help:", "<Ctrl-b>"), ("Search:", "<Enter>"), ("Toggle search mode:", "<Ctrl-n>")]
            status = build_status_bar(hints, RW)
        elif self.active_pane == ActivePane.REPLACE:
            hints = [("Help:", "<Ctrl-b>"), ("Replace:", "<C-o>"), ("Toggle replace mode:", "<Ctrl-n>")]
            status = build_status_bar(hints, RW)
        elif self.active_pane == ActivePane.RESULTS:
            if self.in_file_expanded:
                hints = [("Help:", "<Ctrl-b>"), ("Back to list:", "<Enter>"), ("Replace Line:", "<r>"),
                         ("Next:", "<j>"), ("Previous:", "<k>"), ("Top:", "<g>"), ("Bottom:", "<G>"),
                         ("Delete line:", "<d>")]
            else:
                hints = [("Help:", "<Ctrl-b>"), ("Open File:", "<Enter>"), ("Replace File:", "<r>"),
                         ("Next:", "<j>"), ("Previous:", "<k>"), ("Top:", "<g>"), ("Bottom:", "<G>"),
                         ("Delete file:", "<d>")]
            status = build_status_bar(hints, RW)
        else:
            status = ""

        addstr(self.stdscr, H-1, 0, status[:W])

    def _draw_help(self, d):
        H, W = d['H'], d['W']
        dw = W; dh = 15; dy = 4; dx = 0; iw = dw - 2
        for i in range(dh):
            addstr(self.stdscr, dy+i, dx, ' ' * dw)
        tabs = "[1] Global ─ [2] Navigation"
        close = "Press 'q' to close"
        prefix = " " + tabs + " "
        mid = iw - len(prefix) - len(close)
        title_line = (prefix + '─' * max(0, mid) + close)[:iw]
        addstr(self.stdscr, dy, dx, '╭' + title_line + '╮')
        for i in range(1, dh-1):
            addstr(self.stdscr, dy+i, dx, '│')
            addstr(self.stdscr, dy+i, dx+dw-1, '│')
        addstr(self.stdscr, dy+dh-1, dx, '╰' + '─' * iw + '╯')
        if self.help_tab == 0:
            lines = [
                "", " - Ctrl-c: Quit", " - Ctrl-d: Quit", " - Ctrl-b: Help dialog",
                " - Ctrl-o: Process Replace For All Files",
                " - Ctrl-n: Loop through search and replace modes",
                " - Enter: Select/Deselect file",
                " - d: delete file/delete line from the replace process",
                " - r: Replace Selected File Or Line", "",
            ]
        else:
            lines = [
                "", " - Tab: Loop through panes", " - j/UpArrow: Move up",
                " - k/DownArrow: Move down", " - h/g/LeftArrow: Move to Top",
                " - l/G/RightArrow: Move to Bottom", "",
            ]
        for i, line in enumerate(lines):
            if 1+i >= dh-1: break
            addstr(self.stdscr, dy+1+i, dx+1, line[:iw].ljust(iw))

    def _draw_confirm(self, d):
        H, W = d['H'], d['W']
        dw = 56; dh = 8; iw = dw - 2
        dx = (W - dw) // 2; dy = 8
        title = "Confirm Dialog"
        pad_l = (iw - len(title)) // 2
        pad_r = iw - len(title) - pad_l
        title_bar = '─' * pad_l + title + '─' * pad_r
        addstr(self.stdscr, dy, dx, '╭' + title_bar[:iw] + '╮')
        for i in range(1, dh-1):
            addstr(self.stdscr, dy+i, dx, '│')
            addstr(self.stdscr, dy+i, dx+dw-1, '│')
        addstr(self.stdscr, dy+dh-1, dx, '╰' + '─' * iw + '╯')
        content = [
            "",
            "This action will modify the files in this directory.",
            "Are you sure you want to continue?",
            "", "",
            "Continue  Cancel",
        ]
        for i, text in enumerate(content):
            if 1+i >= dh-1: break
            if text:
                pad = iw - len(text); lp = pad // 2; rp = pad - lp
                line = ' ' * lp + text + ' ' * rp
            else:
                line = ' ' * iw
            addstr(self.stdscr, dy+1+i, dx+1, line[:iw])

    def _draw_notif(self, d):
        H, W = d['H'], d['W']
        msg = self.notification or ""
        nw = min(len(msg) + 4, W - 10)
        iw = nw - 2
        nx = max(0, W - nw - 5)
        ny = H - 3 - 4
        title = "Notification"
        title_bar = title + '─' * max(0, iw - len(title))
        addstr(self.stdscr, ny, nx, '╭' + title_bar[:iw] + '╮')
        addstr(self.stdscr, ny+1, nx, '│' + msg[:iw].ljust(iw) + '│')
        addstr(self.stdscr, ny+2, nx, '╰' + '─' * iw + '╯')

    def _cursor(self, d):
        if self.active_pane == ActivePane.SEARCH:
            cx = min(len(self.search_text), d['LW']-2)
            try: self.stdscr.move(1, 1+cx)
            except curses.error: pass
        elif self.active_pane == ActivePane.REPLACE:
            cx = min(len(self.replace_text), d['LW']-2) if self.replace_mode != ReplaceMode.DELETE_LINE else 0
            try: self.stdscr.move(d['SH']+1, 1+cx)
            except curses.error: pass
        else:
            try: self.stdscr.move(d['H']-1, 0)
            except curses.error: pass


def main():
    import argparse
    parser = argparse.ArgumentParser(prog='executable',
        description='A simple terminal UI for search and replace, ala VS Code')
    parser.add_argument('-p', '--project-root', default='.', metavar='PATH',
        help='Path to the project root [default: .]')
    parser.add_argument('-V', '--version', action='store_true', help='Print version')
    args = parser.parse_args()
    if args.version:
        config_dir = Path.home() / '.config' / 'serpl'
        print(f"serpl {VERSION} ({BUILD_DATE})")
        print()
        print(f"Authors: {AUTHOR}")
        print()
        print(f"Config directory: {config_dir}")
        return
    project_root = os.path.abspath(args.project_root)
    config = load_config()
    curses.wrapper(lambda stdscr: SerplApp(stdscr, project_root, config).run())


if __name__ == '__main__':
    main()
